INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,51,'Al-An''aam','وَأَنذِرۡ بِهِ ٱلَّذِينَ يَخَافُونَ أَن يُحۡشَرُوٓاْ إِلَىٰ رَبِّهِمۡ لَيۡسَ لَهُم مِّن دُونِهِۦ وَلِيࣱّ وَلَا شَفِيعࣱ لَّعَلَّهُمۡ يَتَّقُونَ','اور جو لوگ جو خوف رکھتے ہیں کہ اپنے پروردگار کے روبرو حاضر کئے جائیں گے (اور جانتے ہیں کہ) اس کے سوا نہ تو ان کا کوئی دوست ہوگا اور نہ سفارش کرنے والا، ان کو اس (قرآن) کے ذریعے سے نصیحت کر دو تاکہ پرہیزگار بنیں','Warn with this ˹Quran˺ those who are awed by the prospect of being gathered before their Lord—when they will have no protector or intercessor besides Him—so perhaps they will be mindful ˹of Him˺','और इस क़ुरान के ज़रिए से तुम उन लोगों को डराओ जो इस बात का ख़ौफ रखते हैं कि वह (मरने के बाद) अपने ख़ुदा के सामने जमा किये जायेंगे (और यह समझते है कि) उनका ख़ुदा के सिवा न कोई सरपरस्त हे और न कोई सिफारिश करने वाला ताकि ये लोग परहेज़गार बन जाएं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,52,'Al-An''aam','وَلَا تَطۡرُدِ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ يُرِيدُونَ وَجۡهَهُۥۖ مَا عَلَيۡكَ مِنۡ حِسَابِهِم مِّن شَيۡءࣲ وَمَا مِنۡ حِسَابِكَ عَلَيۡهِم مِّن شَيۡءࣲ فَتَطۡرُدَهُمۡ فَتَكُونَ مِنَ ٱلظَّٰلِمِينَ','اور جو لوگ صبح وشام اپنی پروردگار سے دعا کرتے ہیں (اور) اس کی ذات کے طالب ہیں ان کو (اپنے پاس سے) مت نکالو۔ ان کے حساب (اعمال) کی جوابدہی تم پر کچھ نہیں اور تمہارے حساب کی جوابدہی ان پر کچھ نہیں (پس ایسا نہ کرنا) اگر ان کو نکالوگے تو ظالموں میں ہوجاؤ گے','˹O Prophet!˺ Do not dismiss those ˹poor believers˺ who invoke their Lord morning and evening, seeking His pleasure. You are not accountable for them whatsoever, nor are they accountable for you. So do not dismiss them, or you will be one of the wrongdoers','और (ऐ रसूल) जो लोग सुबह व शाम अपने परवरदिगार से उसकी ख़ुशनूदी की तमन्ना में दुऑए मॉगा करते हैं- उनको अपने पास से न धुत्कारो-न उनके (हिसाब किताब की) जवाब देही कुछ उनके ज़िम्मे है ताकि तुम उन्हें (इस ख्याल से) धुत्कार बताओ तो तुम ज़ालिम (के शुमार) में हो जाओगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,53,'Al-An''aam','وَكَذَٰلِكَ فَتَنَّا بَعۡضَهُم بِبَعۡضࣲ لِّيَقُولُوٓاْ أَهَٰٓؤُلَآءِ مَنَّ ٱللَّهُ عَلَيۡهِم مِّنۢ بَيۡنِنَآۗ أَلَيۡسَ ٱللَّهُ بِأَعۡلَمَ بِٱلشَّٰكِرِينَ','اور اسی طرح ہم نے بعض لوگوں کی بعض سے آزمائش کی ہے کہ (جو دولتمند ہیں وہ غریبوں کی نسبت) کہتے ہیں کیا یہی لوگ ہیں جن پر خدا نے ہم میں سے فضل کیا ہے (خدا نے فرمایا) بھلا خدا شکر کرنے والوں سے واقف نہیں؟','In this way We have tested some by means of others, so those ˹disbelievers˺ may say, “Has Allah favoured these ˹poor believers˺ out of all of us?” Does Allah not best recognize the grateful','और इसी तरह हमने बाज़ आदमियों को बाज़ से आज़माया ताकि वह लोग कहें कि हाएं क्या ये लोग हममें से हैं जिन पर ख़ुदा ने अपना फ़जल व करम किया है (यह तो समझते की) क्या ख़ुदा शुक्र गुज़ारों को भी नही जानता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,54,'Al-An''aam','وَإِذَا جَآءَكَ ٱلَّذِينَ يُؤۡمِنُونَ بِـَٔايَٰتِنَا فَقُلۡ سَلَٰمٌ عَلَيۡكُمۡۖ كَتَبَ رَبُّكُمۡ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَ أَنَّهُۥ مَنۡ عَمِلَ مِنكُمۡ سُوٓءَۢا بِجَهَٰلَةࣲ ثُمَّ تَابَ مِنۢ بَعۡدِهِۦ وَأَصۡلَحَ فَأَنَّهُۥ غَفُورࣱ رَّحِيمࣱ‏','اور جب تمہارے پاس ایسے لوگ آیا کریں جو ہماری آیتوں پر ایمان لاتے ہیں تو (ان سے) سلام علیکم کہا کرو خدا نے اپنی ذات (پاک) پر رحمت کو لازم کرلیا ہے کہ جو کوئی تم میں نادانی سے کوئی بری حرکت کر بیٹھے پھر اس کے بعد توبہ کرلے اور نیکوکار ہوجائے تو وہ بخشنے والا مہربان ہے','When the believers in Our revelations come to you, say, “Peace be upon you! Your Lord has taken upon Himself to be Merciful. Whoever among you commits evil ignorantly ˹or recklessly˺ then repents afterwards and mends their ways, then Allah is truly All-Forgiving, Most Merciful.”','और जो लोग हमारी आयतों पर ईमान लाए हैं तुम्हारे पास ऑंए तो तुम सलामुन अलैकुम (तुम पर ख़ुदा की सलामती हो) कहो तुम्हारे परवरदिगार ने अपने ऊपर रहमत लाज़िम कर ली है बेशक तुम में से जो शख़्श नादानी से कोई गुनाह कर बैठे उसके बाद फिर तौबा करे और अपनी हालत की (असलाह करे ख़ुदा उसका गुनाह बख्श देगा क्योंकि) वह यक़ीनी बड़ा बख्शने वाला मेहरबान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,55,'Al-An''aam','وَكَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ وَلِتَسۡتَبِينَ سَبِيلُ ٱلۡمُجۡرِمِينَ','اور اس طرح ہم اپنی آیتیں کھول کھول کر بیان کرتے ہیں (تاکہ تم لوگ ان پر عمل کرو) اور اس لئے کہ گنہگاروں کا رستہ ظاہر ہوجائے','This is how We make Our signs clear, so the way of the wicked may become distinct','और हम (अपनी) आयतों को यूं तफ़सील से बयान करते हैं ताकि गुनाहगारों की राह (सब पर) खुल जाए और वह इस पर न चले');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,56,'Al-An''aam','قُلۡ إِنِّي نُهِيتُ أَنۡ أَعۡبُدَ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِۚ قُل لَّآ أَتَّبِعُ أَهۡوَآءَكُمۡ قَدۡ ضَلَلۡتُ إِذࣰ ا وَمَآ أَنَا۠ مِنَ ٱلۡمُهۡتَدِينَ','(اے پیغمبر! کفار سے) کہہ دو کہ جن کو تم خدا کے سوا پکارتے ہو مجھے ان کی عبادت سے منع کیا گیا ہے۔ (یہ بھی) کہہ دو کہ میں تمہاری خواہشوں کی پیروی نہیں کروں گا ایسا کروں تو گمراہ ہوجاؤں اور ہدایت یافتہ لوگوں میں نہ رہوں','Say, ˹O Prophet,˺ “I have been forbidden to worship those you invoke besides Allah.” Say, “I will not follow your desires, for I then would certainly be astray and not one of those ˹rightly˺ guided.”','(ऐ रसूल) तुम कह दो कि मुझसे उसकी मनाही की गई है कि मैं ख़ुदा को छोड़कर उन माबूदों की इबादत करुं जिन को तुम पूजा करते हो (ये भी) कह दो कि मै तो तुम्हारी (नाफसानी) ख्वाहिश पर चलने का नहीं (वरना) फिर तो मै गुमराह हो जाऊॅगा और हिदायत याफता लोगों में न रहूँगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,57,'Al-An''aam','قُلۡ إِنِّي عَلَىٰ بَيِّنَةࣲ مِّن رَّبِّي وَكَذَّبۡتُم بِهِۦۚ مَا عِندِي مَا تَسۡتَعۡجِلُونَ بِهِۦٓۚ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ يَقُصُّ ٱلۡحَقَّۖ وَهُوَ خَيۡرُ ٱلۡفَٰصِلِينَ','کہہ دو کہ میں تو اپنے پروردگار کی دلیل روشن پر ہوں اور تم اس کی تکذیب کرتے ہو۔ جس چیز (یعنی عذاب) کے لئے تم جلدی کر رہے ہو وہ میرے پاس نہیں ہے (ایسا) حکم الله ہی کے اختیار میں ہے وہ سچی بات بیان فرماتا ہے اور وہ سب سے بہتر فیصلہ کرنے والا ہے','Say, ˹O Prophet,˺ “Indeed, I stand on a clear proof from my Lord—yet you have denied it. That ˹torment˺ you seek to hasten is not within my power. It is only Allah Who decides ˹its time˺. He declares the truth. And He is the Best of Judges.”','तुम कह दो कि मै तो अपने परवरदिगार की तरफ से एक रौशन दलील पर हूं और तुमने उसे झुठला दिया (तो) तुम जिस की जल्दी करते हो (अज़ाब) वह कुछ मेरे पास (एख्तियार में) तो है नहीं हुकूमत तो बस ज़रुर ख़ुदा ही के लिए है वह तो (हक़) बयान करता है और वह तमाम फैसला करने वालों से बेहतर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,58,'Al-An''aam','قُل لَّوۡ أَنَّ عِندِي مَا تَسۡتَعۡجِلُونَ بِهِۦ لَقُضِيَ ٱلۡأَمۡرُ بَيۡنِي وَبَيۡنَكُمۡۗ وَٱللَّهُ أَعۡلَمُ بِٱلظَّٰلِمِينَ','کہہ دو کہ جس چیز کے لئے تم جلدی کر رہے ہو اگر وہ میرے اختیار میں ہوتی تو مجھ میں اور تم میں فیصلہ ہوچکا ہوتا۔ اور خدا ظالموں سے خوب واقف ہے','Say ˹also˺, “If what you seek to hasten were within my power, the matter between us would have already been settled. But Allah knows the wrongdoers best.”','(उन लोगों से) कह दो कि जिस (अज़ाब) की तुम जल्दी करते हो अगर वह मेरे पास (एख्तियार में) होता तो मेरे और तुम्हारे दरमियान का फैसला कब का चुक गया होता और ख़ुदा तो ज़ालिमों से खूब वाक़िफ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,59,'Al-An''aam','۞وَعِندَهُۥ مَفَاتِحُ ٱلۡغَيۡبِ لَا يَعۡلَمُهَآ إِلَّا هُوَۚ وَيَعۡلَمُ مَا فِي ٱلۡبَرِّ وَٱلۡبَحۡرِۚ وَمَا تَسۡقُطُ مِن وَرَقَةٍ إِلَّا يَعۡلَمُهَا وَلَا حَبَّةࣲ فِي ظُلُمَٰتِ ٱلۡأَرۡضِ وَلَا رَطۡبࣲ وَلَا يَابِسٍ إِلَّا فِي كِتَٰبࣲ مُّبِينࣲ‏','اور اسی کے پاس غیب کی کنجیاں ہیں جن کو اس کے سوا کوئی نہیں جانتا۔ اور اسے جنگلوں اور دریاؤں کی سب چیزوں کا علم ہے۔ اور کوئی پتہ نہیں جھڑتا مگر وہ اس کو جانتا ہے اور زمین کے اندھیروں میں کوئی دانہ اور کوئی ہری اور سوکھی چیز نہیں ہے مگر کتاب روشن میں (لکھی ہوئی) ہے','With Him are the keys of the unseen—no one knows them except Him. And He knows what is in the land and sea. Not even a leaf falls without His knowledge, nor a grain in the darkness of the earth or anything—green or dry—but is ˹written˺ in a perfect Record','और उसके पास ग़ैब की कुन्जियॉ हैं जिनको उसके सिवा कोई नही जानता और जो कुछ ख़ुशकी और तरी में है उसको (भी) वही जानता है और कोई पत्ता भी नहीं खटकता मगर वह उसे ज़रुर जानता है और ज़मीन की तारिक़ियों में कोई दाना और न कोई ख़ुश्क चीज़ है मगर वह नूरानी किताब (लौहे महफूज़) में मौजूद है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,60,'Al-An''aam','وَهُوَ ٱلَّذِي يَتَوَفَّىٰكُم بِٱلَّيۡلِ وَيَعۡلَمُ مَا جَرَحۡتُم بِٱلنَّهَارِ ثُمَّ يَبۡعَثُكُمۡ فِيهِ لِيُقۡضَىٰٓ أَجَلࣱ مُّسَمࣰّ ىۖ ثُمَّ إِلَيۡهِ مَرۡجِعُكُمۡ ثُمَّ يُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ','اور وہی تو ہے جو رات کو (سونے کی حالت میں) تمہاری روح قبض کرلیتا ہے اور جو کچھ تم دن میں کرتے ہو اس سے خبر رکھتا ہے پھر تمہیں دن کو اٹھا دیتا ہے تاکہ (یہی سلسلہ جاری رکھ کر زندگی کی) معین مدت پوری کردی جائے پھر تم (سب) کو اسی کی طرف لوٹ کر جانا ہے (اس روز) وہ تم کو تمہارے عمل جو تم کرتے ہو (ایک ایک کرکے) بتائے گا','He is the One Who calls back your souls by night and knows what you do by day, then revives you daily to complete your appointed term. To Him is your ˹ultimate˺ return, then He will inform you of what you used to do','वह वही (ख़ुदा) है जो तुम्हें रात को (नींद में एक तरह पर दुनिया से) उठा लेता हे और जो कुछ तूने दिन को किया है जानता है फिर तुम्हें दिन को उठा कर खड़ा करता है ताकि (ज़िन्दगी की) (वह) मियाद जो (उसके इल्म में) मुअय्युन है पूरी की जाए फिर (तो आख़िर) तुम सबको उसी की तरफ लौटना है फिर जो कुछ तुम (दुनिया में भला बुरा) करते हो तुम्हें बता देगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,61,'Al-An''aam','وَهُوَ ٱلۡقَاهِرُ فَوۡقَ عِبَادِهِۦۖ وَيُرۡسِلُ عَلَيۡكُمۡ حَفَظَةً حَتَّىٰٓ إِذَا جَآءَ أَحَدَكُمُ ٱلۡمَوۡتُ تَوَفَّتۡهُ رُسُلُنَا وَهُمۡ لَا يُفَرِّطُونَ','اور وہ اپنے بندوں پر غالب ہے۔ اور تم پر نگہبان مقرر کئے رکھتا ہے۔ یہاں تک کہ جب تم میں سے کسی کی موت آتی ہے تو ہمارے فرشتے اس کی روح قبض کرلیتے ہیں اور وہ کسی طرح کی کوتاہی نہیں کرتے','He reigns supreme over all of His creation, and sends recording-angels, watching over you. When death comes to any of you, Our angels take their soul, never neglecting this duty','वह अपने बन्दों पर ग़ालिब है वह तुम लोगों पर निगेहबान (फ़रिश्ततें तैनात करके) भेजता है-यहाँ तक कि जब तुम में से किसी की मौत आए तो हमारे भेजे हुये फ़रिश्ते उसको (दुनिया से) उठा लेते हैं और वह (हमारे तामीले हुक्म में ज़रा भी) कोताही नहीं करते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,62,'Al-An''aam','ثُمَّ رُدُّوٓاْ إِلَى ٱللَّهِ مَوۡلَىٰهُمُ ٱلۡحَقِّۚ أَلَا لَهُ ٱلۡحُكۡمُ وَهُوَ أَسۡرَعُ ٱلۡحَٰسِبِينَ','پھر (قیامت کے دن تمام) لوگ اپنے مالک برحق خدا تعالیٰ کے پاس واپس بلائے جائیں گے۔ سن لو کہ حکم اسی کا ہے اور وہ نہایت جلد حساب لینے والا ہے','Then they are ˹all˺ returned to Allah—their True Master. Judgment is His ˹alone˺. And He is the Swiftest Reckoner','फिर ये लोग अपने सच्चे मालिक ख़ुदा के पास वापस बुलाए गए-आगाह रहो कि हुक़ूमत ख़ास उसी के लिए है और वह सबसे ज्यादा हिसाब लेने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,63,'Al-An''aam','قُلۡ مَن يُنَجِّيكُم مِّن ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِ تَدۡعُونَهُۥ تَضَرُّعࣰ ا وَخُفۡيَةࣰ لَّئِنۡ أَنجَىٰنَا مِنۡ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ','کہو بھلا تم کو جنگلوں اور دریاؤں کے اندھیروں سے کون مخلصی دیتا ہے (جب) کہ تم اسے عاجزی اور نیاز پنہانی سے پکارتے ہو (اور کہتے ہو) اگر خدا ہم کو اس (تنگی) سے نجات بخشے تو ہم اس کے بہت شکر گزار ہوں','Say, ˹O Prophet,˺ “Who rescues you from the darkest times on land and at sea? He ˹alone˺ you call upon with humility, openly and secretly: “If You rescue us from this, we will be ever grateful.”','(ऐ रसूल) उनसे पूछो कि तुम ख़ुश्की और तरी के (घटाटोप) ऍधेरों से कौन छुटकारा देता है जिससे तुम गिड़ गिड़ाकर और (चुपके) दुआएं मॉगते हो कि अगर वह हमें (अब की दफ़ा) उस (बला) से छुटकारा दे तो हम ज़रुर उसके शुक्र गुज़ार (बन्दे होकर) रहेगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,64,'Al-An''aam','قُلِ ٱللَّهُ يُنَجِّيكُم مِّنۡهَا وَمِن كُلِّ كَرۡبࣲ ثُمَّ أَنتُمۡ تُشۡرِكُونَ','کہو کہ خدا ہی تم کو اس (تنگی) سے اور ہر سختی سے نجات بخشتا ہے۔ پھر (تم) اس کے ساتھ شرک کرتے ہو','Say, “˹Only˺ Allah rescues you from this and any other distress, yet you associate others with Him ˹in worship˺.”','तुम कहो उन (मुसीबतों) से और हर बला में ख़ुदा तुम्हें नजात देता है (मगर अफसोस) उस पर भी तुम शिर्क करते ही जाते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,65,'Al-An''aam','قُلۡ هُوَ ٱلۡقَادِرُ عَلَىٰٓ أَن يَبۡعَثَ عَلَيۡكُمۡ عَذَابࣰ ا مِّن فَوۡقِكُمۡ أَوۡ مِن تَحۡتِ أَرۡجُلِكُمۡ أَوۡ يَلۡبِسَكُمۡ شِيَعࣰ ا وَيُذِيقَ بَعۡضَكُم بَأۡسَ بَعۡضٍۗ ٱنظُرۡ كَيۡفَ نُصَرِّفُ ٱلۡأٓيَٰتِ لَعَلَّهُمۡ يَفۡقَهُونَ','کہہ دو کہ وہ (اس پر بھی) قدرت رکھتا ہے کہ تم پر اوپر کی طرف سے یا تمہارے پاؤں کے نیچے سے عذاب بھیجے یا تمہیں فرقہ فرقہ کردے اور ایک کو دوسرے (سے لڑا کر آپس) کی لڑائی کا مزہ چکھادے۔ دیکھو ہم اپنی آیتوں کو کس کس طرح بیان کرتے ہیں تاکہ یہ لوگ سمجھیں','Say, “He ˹alone˺ has the power to unleash upon you a torment from above or below you or split you into ˹conflicting˺ factions and make you taste the violence of one another.” See how We vary the signs, so perhaps they will comprehend','(ऐ रसूल) तुम कह दो कि वही उस पर अच्छी तरह क़ाबू रखता है कि अगर (चाहे तो) तुम पर अज़ाब तुम्हारे (सर के) ऊपर से नाज़िल करे या तुम्हारे पॉव के नीचे से (उठाकर खड़ा कर दे) या एक गिरोह को दूसरे से भिड़ा दे और तुम में से कुछ लोगों को बाज़ आदमियों की लड़ाई का मज़ा चखा दे ज़रा ग़ौर तो करो हम किस किस तरह अपनी आयतों को उलट पुलट के बयान करते हैं ताकि लोग समझे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,66,'Al-An''aam','وَكَذَّبَ بِهِۦ قَوۡمُكَ وَهُوَ ٱلۡحَقُّۚ قُل لَّسۡتُ عَلَيۡكُم بِوَكِيلࣲ‏','اور اس (قرآن) کو تمہاری قوم نے جھٹلایا حالانکہ وہ سراسر حق ہے۔ کہہ دو کہ میں تمہارا داروغہ نہیں ہوں','Still your people ˹O Prophet˺ have rejected this ˹Quran˺, although it is the truth. Say, “I am not a keeper over you.”','और उसी (क़ुरान) को तुम्हारी क़ौम ने झुठला दिया हालॉकि वह बरहक़ है (ऐ रसूल) तुम उनसे कहो कि मैं तुम पर कुछ निगेहबान तो हूं नहीं हर ख़बर (के पूरा होने) का एक ख़ास वक्त मुक़र्रर है और अनक़रीब (जल्दी) ही तुम जान लोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,67,'Al-An''aam','لِّكُلِّ نَبَإࣲ مُّسۡتَقَرࣱّۚ وَسَوۡفَ تَعۡلَمُونَ','ہر خبر کے لئے ایک وقت مقرر ہے اور تم کو عنقریب معلوم ہوجائے گا','Every ˹destined˺ matter has a ˹set˺ time to transpire. And you will soon come to know','और जब तुम उन लोगों को देखो जो हमारी आयतों में बेहूदा बहस कर रहे हैं तो उन (के पास) से टल जाओ यहाँ तक कि वह लोग उसके सिवा किसी और बात में बहस करने लगें और अगर (हमारा ये हुक्म) तुम्हें शैतान भुला दे तो याद आने के बाद ज़ालिम लोगों के साथ हरगिज़ न बैठना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,68,'Al-An''aam','وَإِذَا رَأَيۡتَ ٱلَّذِينَ يَخُوضُونَ فِيٓ ءَايَٰتِنَا فَأَعۡرِضۡ عَنۡهُمۡ حَتَّىٰ يَخُوضُواْ فِي حَدِيثٍ غَيۡرِهِۦۚ وَإِمَّا يُنسِيَنَّكَ ٱلشَّيۡطَٰنُ فَلَا تَقۡعُدۡ بَعۡدَ ٱلذِّكۡرَىٰ مَعَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ','اور جب تم ایسے لوگوں کو دیکھو جو ہماری آیتوں کے بارے میں بیہودہ بکواس کر رہے ہوں تو ان سے الگ ہوجاؤ یہاں تک کہ اور باتوں میں مصروف ہوجائیں۔ اور اگر (یہ بات) شیطان تمہیں بھلا دے تو یاد آنے پر ظالم لوگوں کے ساتھ نہ بیٹھو','And when you come across those who ridicule Our revelations, do not sit with them unless they engage in a different topic. Should Satan make you forget, then once you remember, do not ˹continue to˺ sit with the wrongdoing people','और ऐसे लोगों (के हिसाब किताब) का जवाब देही कुछ परहेज़गारो पर तो है नहीं मगर (सिर्फ नसीहतन) याद दिलाना (चाहिए) ताकि ये लोग भी परहेज़गार बनें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,69,'Al-An''aam','وَمَا عَلَى ٱلَّذِينَ يَتَّقُونَ مِنۡ حِسَابِهِم مِّن شَيۡءࣲ وَلَٰكِن ذِكۡرَىٰ لَعَلَّهُمۡ يَتَّقُونَ','اور پرہیزگاروں پر ان لوگوں کے حساب کی کچھ بھی جواب دہی نہیں ہاں نصیحت تاکہ وہ بھی پرہیزگار ہوں','Those mindful ˹of Allah˺ will not be accountable for those ˹who ridicule it˺ whatsoever—their duty is to advise, so perhaps the ridiculers will abstain','और जिन लोगों ने अपने दीन को खेल और तमाशा बना रखा है और दुनिया की ज़िन्दगी ने उन को धोके में डाल रखा है ऐसे लोगों को छोड़ो और क़ुरान के ज़रिए से उनको नसीहत करते रहो (ऐसा न हो कि कोई) शख़्श अपने करतूत की बदौलत मुब्तिलाए बला हो जाए (क्योंकि उस वक्त) तो ख़ुदा के सिवा उसका न कोई सरपरस्त होगा न सिफारिशी और अगर वह अपने गुनाह के ऐवज़ सारे (जहाँन का) बदला भी दे तो भी उनमें से एक न लिया जाएगा जो लोग अपनी करनी की बदौलत मुब्तिलाए बला हुए है उनको पीने के लिए खौलता हुआ गर्म पानी (मिलेगा) और (उन पर) दर्दनाक अज़ाब होगा क्योंकर वह कुफ़्र किया करते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,70,'Al-An''aam','وَذَرِ ٱلَّذِينَ ٱتَّخَذُواْ دِينَهُمۡ لَعِبࣰ ا وَلَهۡوࣰ ا وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ وَذَكِّرۡ بِهِۦٓ أَن تُبۡسَلَ نَفۡسُۢ بِمَا كَسَبَتۡ لَيۡسَ لَهَا مِن دُونِ ٱللَّهِ وَلِيࣱّ وَلَا شَفِيعࣱ وَإِن تَعۡدِلۡ كُلَّ عَدۡلࣲ لَّا يُؤۡخَذۡ مِنۡهَآۗ أُوْلَٰٓئِكَ ٱلَّذِينَ أُبۡسِلُواْ بِمَا كَسَبُواْۖ لَهُمۡ شَرَابࣱ مِّنۡ حَمِيمࣲ وَعَذَابٌ أَلِيمُۢ بِمَا كَانُواْ يَكۡفُرُونَ','اور جن لوگوں نے اپنےدین کو کھیل اور تماشا بنا رکھا ہے اور دنیا کی زندگی نے ان کو دھوکے میں ڈال رکھا ہے ان سے کچھ کام نہ رکھو ہاں اس (قرآن) کے ذریعے سے نصیحت کرتے رہو تاکہ (قیامت کے دن) کوئی اپنے اعمال کی سزا میں ہلاکت میں نہ ڈالا جائے (اس روز) خدا کےسوا نہ تو کوئی اس کا دوست ہوگا اور نہ سفارش کرنے والا۔ اور اگر وہ ہر چیز (جو روئے زمین پر ہے بطور) معاوضہ دینا چاہے تو وہ اس سے قبول نہ ہو یہی لوگ ہیں کہ اپنے اعمال کے وبال میں ہلاکت میں ڈالے گئے ان کے لئے پینے کو کھولتا ہوا پانی اور دکھ دینے والا عذاب ہے اس لئے کہ کفر کرتے تھے','And leave those who take this faith ˹of Islam˺ as mere play and amusement and are deluded by ˹their˺ worldly life. Yet remind them by this ˹Quran˺, so no one should be ruined for their misdeeds. They will have no protector or intercessor other than Allah. Even if they were to offer every ˹possible˺ ransom, none will be accepted from them. Those are the ones who will be ruined for their misdeeds. They will have a boiling drink and painful punishment for their disbelief','(ऐ रसूल) उनसे पूछो तो कि क्या हम लोग ख़ुदा को छोड़कर उन (माबूदों) से मुनाज़ात (दुआ) करे जो न तो हमें नफ़ा पहुंचा सकते हैं न हमारा कुछ बिगाड़ ही सकते हैं- और जब ख़ुदा हमारी हिदायत कर चुका) उसके बाद उल्टे पावँ कुफ्र की तरफ उस शख़्श की तरह फिर जाएं जिसे शैतानों ने जंगल में भटका दिया हो और वह हैरान (परेशान) हो (कि कहा जाए क्या करें) और उसके कुछ रफीक़ हो कि उसे राहे रास्त (सीधे रास्ते) की तरफ पुकारते रह जाएं कि (उधर) हमारे पास आओ और वह एक न सुने (ऐ रसूल) तुम कह दो कि हिदायत तो बस ख़ुदा की हिदायत है और हमें तो हुक्म ही दिया गया है कि हम सारे जहॉन के परवरदिगार ख़ुदा के फरमाबरदार हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,71,'Al-An''aam','قُلۡ أَنَدۡعُواْ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَىٰٓ أَعۡقَابِنَا بَعۡدَ إِذۡ هَدَىٰنَا ٱللَّهُ كَٱلَّذِي ٱسۡتَهۡوَتۡهُ ٱلشَّيَٰطِينُ فِي ٱلۡأَرۡضِ حَيۡرَانَ لَهُۥٓ أَصۡحَٰبࣱ يَدۡعُونَهُۥٓ إِلَى ٱلۡهُدَى ٱئۡتِنَاۗ قُلۡ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلۡهُدَىٰۖ وَأُمِرۡنَا لِنُسۡلِمَ لِرَبِّ ٱلۡعَٰلَمِينَ','کہو۔ کیا ہم خدا کے سوا ایسی چیز کو پکاریں جو نہ ہمارا بھلا کرسکے نہ برا۔ اور جب ہم کو خدا نے سیدھا رستہ دکھا دیا تو (کیا) ہم الٹے پاؤں پھر جائیں؟ (پھر ہماری ایسی مثال ہو) جیسے کسی کو جنات نے جنگل میں بھلا دیا ہو (اور وہ) حیران (ہو رہا ہو) اور اس کے کچھ رفیق ہوں جو اس کو رستے کی طرف بلائیں کہ ہمارے پاس چلا آ۔ کہہ دو کہ رستہ تو وہی ہے جو خدا نے بتایا ہے۔ اور ہمیں تو یہ حکم ملا ہے کہ ہم خدائے رب العالمین کے فرمانبردار ہوں','Ask ˹them, O Prophet˺, “Should we invoke, other than Allah, those ˹idols˺ which cannot benefit or harm us, and turn back to disbelief after Allah has guided us? ˹If we do so, we will be˺ like those disoriented by devils in the wilderness, while their companions call them to guidance, ˹saying˺, ‘Come to us!’ Say, ˹O Prophet,˺ “Allah’s guidance is the ˹only˺ true guidance. And we are commanded to submit to the Lord of all worlds','और ये (भी हुक्म हुआ है) कि पाबन्दी से नमाज़ पढ़ा करो और उसी से डरते रहो और वही तो वह (ख़ुदा) है जिसके हुज़ूर में तुम सब के सब हाज़िर किए जाओगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,72,'Al-An''aam','وَأَنۡ أَقِيمُواْ ٱلصَّلَوٰةَ وَٱتَّقُوهُۚ وَهُوَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ','اور یہ (بھی) کہ نماز پڑھتے رہو اور اس سے ڈرتے رہو۔ اور وہی تو ہے جس کے پاس تم جمع کئے جاؤ گے','establish prayer, and be mindful of Him. To Him you will all be gathered together','वह तो वह (ख़ुदा है) जिसने ठीक ठीक बहुतेरे आसमान व ज़मीन पैदा किए और जिस दिन (किसी चीज़ को) कहता है कि हो जा तो (फौरन) हो जाती है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,73,'Al-An''aam','وَهُوَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۖ وَيَوۡمَ يَقُولُ كُن فَيَكُونُۚ قَوۡلُهُ ٱلۡحَقُّۚ وَلَهُ ٱلۡمُلۡكُ يَوۡمَ يُنفَخُ فِي ٱلصُّورِۚ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡخَبِيرُ','اور وہی تو ہے جس نے آسمانوں اور زمین کو تدبیر سے پیدا کیا ہے۔ اور جس دن وہ فرمائے گا کہ ہو جا تو (حشر برپا) ہوجائے گا ۔ اس کا ارشاد برحق ہے۔ اور جس دن صور پھونکا جائے گا (اس دن) اسی کی بادشاہت ہوگی۔ وہی پوشیدہ اور ظاہر (سب) کا جاننے والا ہے اور وہی دانا اور خبردار ہے','He is the One Who created the heavens and the earth in truth. On the Day ˹of Judgment˺ He will say, ‘Be!’ And there will be! His command is truth. All authority is His ˹alone˺ on the Day the Trumpet will be blown. He is the Knower of all—seen or unseen. And He is the All-Wise, All-Aware.”','उसका क़ौल सच्चा है और जिस दिन सूर फूंका जाएगा (उस दिन) ख़ास उसी की बादशाहत होगी (वही) ग़ायब हाज़िर (सब) का जानने वाला है और वही दाना वाक़िफकार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,74,'Al-An''aam','۞وَإِذۡ قَالَ إِبۡرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصۡنَامًا ءَالِهَةً إِنِّيٓ أَرَىٰكَ وَقَوۡمَكَ فِي ضَلَٰلࣲ مُّبِينࣲ‏','اور (وہ وقت بھی یاد کرنے کے لائق ہے) جب ابراہیم نے اپنے باپ آزر سے کہا کہ تم بتوں کو کیا معبود بناتے ہو۔ میں دیکھتا ہوں کہ تم اور تمہاری قوم صریح گمراہی میں ہو','And ˹remember˺ when Abraham said to his father, Ȃzar, “Do you take idols as gods? It is clear to me that you and your people are entirely misguided.”','(ऐ रसूल) उस वक्त क़ा याद करो) जब इबराहीम ने अपने (मुंह बोले) बाप आज़र से कहा क्या तुम बुतों को ख़ुदा मानते हो-मै तो तुमको और तुम्हारी क़ौम को खुली गुमराही में देखता हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,75,'Al-An''aam','وَكَذَٰلِكَ نُرِيٓ إِبۡرَٰهِيمَ مَلَكُوتَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلِيَكُونَ مِنَ ٱلۡمُوقِنِينَ','اور ہم اس طرح ابراہیم کو آسمانوں اور زمین کے عجائبات دکھانے لگے تاکہ وہ خوب یقین کرنے والوں میں ہوجائیں','We also showed Abraham the wonders of the heavens and the earth, so he would be sure in faith','और (जिस तरह हमने इबराहीम को दिखाया था कि बुत क़ाबिले परसतिश (पूजने के क़ाबिल) नहीं) उसी तरह हम इबराहीम को सारे आसमान और ज़मीन की सल्तनत का (इन्तज़ाम) दिखाते रहे ताकि वह (हमारी वहदानियत का) यक़ीन करने वालों से हो जाएं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,76,'Al-An''aam','فَلَمَّا جَنَّ عَلَيۡهِ ٱلَّيۡلُ رَءَا كَوۡكَبࣰ اۖ قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلۡأٓفِلِينَ','(یعنی) جب رات نے ان کو (پردہٴ تاریکی سے) ڈھانپ لیا (تو آسمان میں) ایک ستارا نظر پڑا۔ کہنے لگے یہ میرا پروردگار ہے۔ جب وہ غائب ہوگیا تو کہنے لگے کہ مجھے غائب ہوجانے والے پسند نہیں','When the night grew dark upon him, he saw a star and said, “This is my Lord!” But when it set, he said, “I do not love things that set.”','तो जब उन पर रात की तारीक़ी (अंधेरा) छा गयी तो एक सितारे को देखा तो दफअतन बोल उठे (हाए क्या) यही मेरा ख़ुदा है फिर जब वह डूब गया तो कहने लगे ग़ुरुब (डूब) हो जाने वाली चीज़ को तो मै (ख़ुदा बनाना) पसन्द नहीं करता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,77,'Al-An''aam','فَلَمَّا رَءَا ٱلۡقَمَرَ بَازِغࣰ ا قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمۡ يَهۡدِنِي رَبِّي لَأَكُونَنَّ مِنَ ٱلۡقَوۡمِ ٱلضَّآلِّينَ','پھر جب چاند کو دیکھا کہ چمک رہا ہے تو کہنے لگے یہ میرا پروردگار ہے۔ لیکن جب وہ بھی چھپ گیا تو بول اٹھے کہ میرا پروردگار مجھے سیدھا رستہ نہیں دکھائے گا تو میں ان لوگوں میں ہوجاؤں گا جو بھٹک رہے ہیں','Then when he saw the moon rising, he said, “This one is my Lord!” But when it disappeared, he said, “If my Lord does not guide me, I will certainly be one of the misguided people.”','फिर जब चाँद को जगमगाता हुआ देखा तो बोल उठे (क्या) यही मेरा ख़ुदा है फिर जब वह भी ग़ुरुब हो गया तो कहने लगे कि अगर (कहीं) मेरा (असली) परवरदिगार मेरी हिदायत न करता तो मैं ज़रुर गुमराह लोगों में हो जाता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,78,'Al-An''aam','فَلَمَّا رَءَا ٱلشَّمۡسَ بَازِغَةࣰ قَالَ هَٰذَا رَبِّي هَٰذَآ أَكۡبَرُۖ فَلَمَّآ أَفَلَتۡ قَالَ يَٰقَوۡمِ إِنِّي بَرِيٓءࣱ مِّمَّا تُشۡرِكُونَ','پھر جب سورج کو دیکھا کہ جگمگا رہا ہے تو کہنے لگے میرا پروردگار یہ ہے یہ سب سے بڑا ہے۔ مگر جب وہ بھی غروب ہوگیا تو کہنے لگے لوگو! جن چیزوں کو تم (خدا کا) شریک بناتے ہو میں ان سے بیزار ہوں','Then when he saw the sun shining, he said, “This must be my Lord—it is the greatest!” But again when it set, he declared, “O my people! I totally reject whatever you associate ˹with Allah in worship˺','फिर जब आफताब को दमकता हुआ देखा तो कहने लगे (क्या) यही मेरा ख़ुदा है ये तो सबसे बड़ा (भी) है फिर जब ये भी ग़ुरुब हो गया तो कहने लगे ऐ मेरी क़ौम जिन जिन चीज़ों को तुम लोग (ख़ुदा का) शरीक बनाते हो उनसे मैं बेज़ार हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,79,'Al-An''aam','إِنِّي وَجَّهۡتُ وَجۡهِيَ لِلَّذِي فَطَرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ حَنِيفࣰ اۖ وَمَآ أَنَا۠ مِنَ ٱلۡمُشۡرِكِينَ','میں نے سب سے یکسو ہو کر اپنے تئیں اسی ذات کی طرف متوجہ کیا جس نے آسمانوں اور زمین کو پیدا کیا ہے اور میں مشرکوں میں سے نہیں ہوں','I have turned my face towards the One Who has originated the heavens and the earth—being upright—and I am not one of the polytheists.”','(ये हरगिज़ नहीं हो सकते) मैने तो बातिल से कतराकर उसकी तरफ से मुँह कर लिया है जिसने बहुतेरे आसमान और ज़मीन पैदा किए और मैं मुशरेकीन से नहीं हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,80,'Al-An''aam','وَحَآجَّهُۥ قَوۡمُهُۥۚ قَالَ أَتُحَٰٓجُّوٓنِّي فِي ٱللَّهِ وَقَدۡ هَدَىٰنِۚ وَلَآ أَخَافُ مَا تُشۡرِكُونَ بِهِۦٓ إِلَّآ أَن يَشَآءَ رَبِّي شَيۡـࣰٔ اۚ وَسِعَ رَبِّي كُلَّ شَيۡءٍ عِلۡمًاۚ أَفَلَا تَتَذَكَّرُونَ','اور ان کی قوم ان سے بحث کرنے لگی تو انہوں نے کہا کہ تم مجھ سے خدا کے بارےمیں (کیا) بحث کرتے ہو اس نے تو مجھے سیدھا رستہ دکھا دیا ہے۔ اور جن چیزوں کو تم اس کا شریک بناتے ہو میں ان سے نہیں ڈرتا۔ ہاں جو میرا پروردگار چاہے۔ میرا پروردگار اپنے علم سے ہر چیز پر احاطہ کئے ہوئے ہے۔ کیا تم خیال نہیں کرتے۔','And his people argued with him. He responded, “Are you arguing with me about Allah, while He has guided me? I am not afraid of whatever ˹idols˺ you associate with Him—˹none can harm me,˺ unless my Lord so wills. My Lord encompasses everything in ˹His˺ knowledge. Will you not be mindful','और उनकी क़ौम के लोग उनसे हुज्जत करने लगे तो इबराहीम ने कहा था क्या तुम मुझसे ख़ुदा के बारे में हुज्जत करते हो हालॉकि वह यक़ीनी मेरी हिदायत कर चुका और तुम मे जिन बुतों को उसका शरीक मानते हो मै उनसे डरता (वरता) नहीं (वह मेरा कुछ नहीं कर सकते) मगर हॉ मेरा ख़ुदा खुद (करना) चाहे तो अलबत्ता कर सकता है मेरा परवरदिगार तो बाएतबार इल्म के सब पर हावी है तो क्या उस पर भी तुम नसीहत नहीं मानते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,81,'Al-An''aam','وَكَيۡفَ أَخَافُ مَآ أَشۡرَكۡتُمۡ وَلَا تَخَافُونَ أَنَّكُمۡ أَشۡرَكۡتُم بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ عَلَيۡكُمۡ سُلۡطَٰنࣰ اۚ فَأَيُّ ٱلۡفَرِيقَيۡنِ أَحَقُّ بِٱلۡأَمۡنِۖ إِن كُنتُمۡ تَعۡلَمُونَ','بھلا میں ان چیزوں سے جن کو تم (خدا کا) شریک بناتے ہو کیونکرڈروں جب کہ تم اس سے نہیں ڈرتے کہ خدا کے ساتھ شریک بناتے ہو جس کی اس نے کوئی سند نازل نہیں کی۔ اب دونوں فریق میں سے کون سا فریق امن (اور جمعیت خاطر) کا مستحق ہے۔ اگر سمجھ رکھتے ہو (تو بتاؤ)','And how should I fear your associate-gods, while you have no fear in associating ˹others˺ with Allah—a practice He has never authorized? Which side has more right to security? ˹Tell me˺ if you really know!”','और जिन्हें तुम ख़ुदा का शरीक बताते हो मै उन से क्यों डरुँ जब तुम इस बात से नहीं डरते कि तुमने ख़ुदा का शरीक ऐसी चीज़ों को बनाया है जिनकी ख़ुदा ने कोई सनद तुम पर नहीं नाज़िल की फिर अगर तुम जानते हो तो (भला बताओ तो सही कि) हम दोनों फरीक़ (गिरोह) में अमन क़ायम रखने का ज्यादा हक़दार कौन है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,82,'Al-An''aam','ٱلَّذِينَ ءَامَنُواْ وَلَمۡ يَلۡبِسُوٓاْ إِيمَٰنَهُم بِظُلۡمٍ أُوْلَٰٓئِكَ لَهُمُ ٱلۡأَمۡنُ وَهُم مُّهۡتَدُونَ','جو لوگ ایمان لائے اور اپنے ایمان کو (شرک کے) ظلم سے مخلوط نہیں کیا ان کے امن (اور جمعیت خاطر) ہے اور وہی ہدایت پانے والے ہیں','It is ˹only˺ those who are faithful and do not tarnish their faith with falsehood who are guaranteed security and are ˹rightly˺ guided','जिन लोगों ने ईमान क़ुबूल किया और अपने ईमान को ज़ुल्म (शिर्क) से आलूदा नहीं किया उन्हीं लोगों के लिए अमन (व इतमिनान) है और यही लोग हिदायत याफ़ता हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,83,'Al-An''aam','وَتِلۡكَ حُجَّتُنَآ ءَاتَيۡنَٰهَآ إِبۡرَٰهِيمَ عَلَىٰ قَوۡمِهِۦۚ نَرۡفَعُ دَرَجَٰتࣲ مَّن نَّشَآءُۗ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمࣱ‏','اور یہ ہماری دلیل تھی جو ہم نے ابراہیم کو ان کی قوم کے مقابلے میں عطا کی تھی۔ ہم جس کے چاہتے ہیں درجے بلند کردیتے ہیں۔ بےشک تمہارا پروردگار دانا اور خبردار ہے','This was the argument We gave Abraham against his people. We elevate in rank whoever We please. Surely your Lord is All-Wise, All-Knowing','और ये हमारी (समझाई बुझाई) दलीलें हैं जो हमने इबराहीम को अपनी क़ौम पर (ग़ालिब आने के लिए) अता की थी हम जिसके मरतबे चाहते हैं बुलन्द करते हैं बेशक तुम्हारा परवरदिगार हिक़मत वाला बाख़बर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,84,'Al-An''aam','وَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَۚ كُلًّا هَدَيۡنَاۚ وَنُوحًا هَدَيۡنَا مِن قَبۡلُۖ وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيۡمَٰنَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَٰرُونَۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ','اور ہم نے ان کو اسحاق اور یعقوب بخشے۔ (اور) سب کو ہدایت دی۔ اور پہلے نوح کو بھی ہدایت دی تھی اور ان کی اولاد میں سے داؤد اور سلیمان اور ایوب اور یوسف اور موسیٰ اور ہارون کو بھی۔ اور ہم نیک لوگوں کو ایسا ہی بدلا دیا کرتے ہیں','And We blessed him with Isaac and Jacob. We guided them all as We previously guided Noah and those among his descendants: David, Solomon, Job, Joseph, Moses, and Aaron. This is how We reward the good-doers','और हमने इबराहीम को इसहाक़ वा याक़ूब (सा बेटा पोता) अता किया हमने सबकी हिदायत की और उनसे पहले नूह को (भी) हम ही ने हिदायत की और उन्हीं (इबराहीम) को औलाद से दाऊद व सुलेमान व अय्यूब व यूसुफ व मूसा व हारुन (सब की हमने हिदायत की) और नेकों कारों को हम ऐसा ही इल्म अता फरमाते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,85,'Al-An''aam','وَزَكَرِيَّا وَيَحۡيَىٰ وَعِيسَىٰ وَإِلۡيَاسَۖ كُلࣱّ مِّنَ ٱلصَّٰلِحِينَ','اور زکریا اور یحییٰ اور عیسیٰ اور الیاس کو بھی۔ یہ سب نیکوکار تھے','Likewise, ˹We guided˺ Zachariah, John, Jesus, and Elias, who were all of the righteous','और ज़करिया व यहया व ईसा व इलियास (सब की हिदायत की (और ये) सब (ख़ुदा के) नेक बन्दों से हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,86,'Al-An''aam','وَإِسۡمَٰعِيلَ وَٱلۡيَسَعَ وَيُونُسَ وَلُوطࣰ اۚ وَكُلࣰّ ا فَضَّلۡنَا عَلَى ٱلۡعَٰلَمِينَ','اور اسمٰعیل اور الیسع اور یونس اور لوط کو بھی۔ اور ان سب کو جہان کے لوگوں پر فضلیت بخشی تھی','˹We also guided˺ Ishmael, Elisha, Jonah, and Lot, favouring each over other people ˹of their time˺','और इसमाइल व इलियास व युनूस व लूत (की भी हिदायत की) और सब को सारे जहाँन पर फज़ीलत अता की');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,87,'Al-An''aam','وَمِنۡ ءَابَآئِهِمۡ وَذُرِّيَّٰتِهِمۡ وَإِخۡوَٰنِهِمۡۖ وَٱجۡتَبَيۡنَٰهُمۡ وَهَدَيۡنَٰهُمۡ إِلَىٰ صِرَٰطࣲ مُّسۡتَقِيمࣲ‏','اور بعض بعض کو ان کے باپ دادا اور اولاد اور بھائیوں میں سے بھی۔ اور ان کو برگزیدہ بھی کیا تھا اور سیدھا رستہ بھی دکھایا تھا','And ˹We favoured˺ some of their forefathers, their descendants, and their brothers. We chose them and guided them to the Straight Path','और (सिर्फ उन्हीं को नहीं बल्कि) उनके बाप दादाओं और उनकी औलाद और उनके भाई बन्दों में से (बहुतेरों को) और उनके मुन्तख़िब किया और उन्हें सीधी राह की हिदायत की');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,88,'Al-An''aam','ذَٰلِكَ هُدَى ٱللَّهِ يَهۡدِي بِهِۦ مَن يَشَآءُ مِنۡ عِبَادِهِۦۚ وَلَوۡ أَشۡرَكُواْ لَحَبِطَ عَنۡهُم مَّا كَانُواْ يَعۡمَلُونَ','یہ خدا کی ہدایت ہے اس پر اپنے بندوں میں سے جسے چاہے چلائے۔ اور اگر وہ لوگ شرک کرتے تو جو عمل وہ کرتے تھے سب ضائع ہوجاتے','This is Allah’s guidance with which He guides whoever He wills of His servants. Had they associated others with Him ˹in worship˺, their ˹good˺ deeds would have been wasted','(देखो) ये ख़ुदा की हिदायत है अपने बन्दों से जिसको चाहे उसीकी वजह से राह पर लाए और अगर उन लोगों ने शिर्क किया होता तो उनका किया (धरा) सब अकारत हो जाता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,89,'Al-An''aam','أُوْلَٰٓئِكَ ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَۚ فَإِن يَكۡفُرۡ بِهَا هَٰٓؤُلَآءِ فَقَدۡ وَكَّلۡنَا بِهَا قَوۡمࣰ ا لَّيۡسُواْ بِهَا بِكَٰفِرِينَ','یہ وہ لوگ تھے جن کو ہم نے کتاب اور حکم (شریعت) اور نبوت عطا فرمائی تھی۔ اگر یہ (کفار) ان باتوں سے انکار کریں تو ہم نے ان پر (ایمان لانے کے لئے) ایسے لوگ مقرر کردیئے ہیں کہ وہ ان سے کبھی انکار کرنے والے نہیں','Those were the ones to whom We gave the Scripture, wisdom, and prophethood. But if these ˹pagans˺ disbelieve in this ˹message˺, then We have already entrusted it to a people who will never disbelieve in it','(पैग़म्बर) वह लोग थे जिनको हमने (आसमानी) किताब और हुकूमत और नुबूवत अता फरमाई पस अगर ये लोग उसे भी न माने तो (कुछ परवाह नहीं) हमने तो उस पर ऐसे लोगों को मुक़र्रर कर दिया हे जो (उनकी तरह) इन्कार करने वाले नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,90,'Al-An''aam','أُوْلَٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُۖ فَبِهُدَىٰهُمُ ٱقۡتَدِهۡۗ قُل لَّآ أَسۡـَٔلُكُمۡ عَلَيۡهِ أَجۡرًاۖ إِنۡ هُوَ إِلَّا ذِكۡرَىٰ لِلۡعَٰلَمِينَ','یہ وہ لوگ ہیں جن کو خدا نے ہدایت دی تھی تو تم انہیں کی ہدایت کی پیروی کرو۔ کہہ دو کہ میں تم سے اس (قرآن) کا صلہ نہیں مانگتا۔ یہ تو جہان کے لوگوں کے لئےمحض نصیحت ہے','These ˹prophets˺ were ˹rightly˺ guided by Allah, so follow their guidance. Say, “I ask no reward of you for this ˹Quran˺—it is a reminder to the whole world.”','(ये अगले पैग़म्बर) वह लोग थे जिनकी ख़ुदा ने हिदायत की पस तुम भी उनकी हिदायत की पैरवी करो (ऐ रसूल उन से) कहो कि मै तुम से इस (रिसालत) की मज़दूरी कुछ नहीं चाहता सारे जहाँन के लिए सिर्फ नसीहत है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,91,'Al-An''aam','وَمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓ إِذۡ قَالُواْ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرࣲ مِّن شَيۡءࣲۗ قُلۡ مَنۡ أَنزَلَ ٱلۡكِتَٰبَ ٱلَّذِي جَآءَ بِهِۦ مُوسَىٰ نُورࣰ ا وَهُدࣰ ى لِّلنَّاسِۖ تَجۡعَلُونَهُۥ قَرَاطِيسَ تُبۡدُونَهَا وَتُخۡفُونَ كَثِيرࣰ اۖ وَعُلِّمۡتُم مَّا لَمۡ تَعۡلَمُوٓاْ أَنتُمۡ وَلَآ ءَابَآؤُكُمۡۖ قُلِ ٱللَّهُۖ ثُمَّ ذَرۡهُمۡ فِي خَوۡضِهِمۡ يَلۡعَبُونَ','اور ان لوگوں نے خدا کی قدر جیسی جاننی چاہیئے تھی نہ جانی۔ جب انہوں نے کہا کہ خدا نے انسان پر (وحی اور کتاب وغیرہ) کچھ بھی نازل نہیں کیا۔ کہو جو کتاب موسیٰ لے کر آئے تھے اسے کس نے نازل کیا تھا جو لوگوں کے لئے نور اور ہدایت تھی اور جسے تم نے علیحدہ علیحدہ اوراق (پر نقل) کر رکھا ہے ان (کے کچھ حصے) کو تو ظاہر کرتے ہو اور اکثر کو چھپاتے ہو۔ اور تم کو وہ باتیں سکھائی گئیں جن کو نہ تم جانتے تھے اور نہ تمہارے باپ دادا۔ کہہ دو (اس کتاب کو) خدا ہی نے (نازل کیا تھا) پھر ان کو چھوڑ دیا کہ اپنی بیہودہ بکواس میں کھیلتے رہیں','And they have not shown Allah His proper reverence when they said, “Allah has revealed nothing to any human being.” Say, ˹O Prophet,˺ “Who then revealed the Book brought forth by Moses as a light and guidance for people, which you split into separate sheets—revealing some and hiding much? You have been taught ˹through this Quran˺ what neither you nor your forefathers knew.” Say, ˹O Prophet,˺ “Allah ˹revealed it˺!” Then leave them to amuse themselves with falsehood','और बस और उन लोगों (यहूद) ने ख़ुदा की जैसी क़दर करनी चाहिए न की इसलिए कि उन लोगों ने (बेहूदे पन से) ये कह दिया कि ख़ुदा ने किसी बशर (इनसान) पर कुछ नाज़िल नहीं किया (ऐ रसूल) तुम पूछो तो कि फिर वह किताब जिसे मूसा लेकर आए थे किसने नाज़िल की जो लोगों के लिए रौशनी और (अज़सरतापा(सर से पैर तक)) हिदायत (थी जिसे तुम लोगों ने अलग-अलग करके काग़जी औराक़ (कागज़ के पन्ने) बना डाला और इसमें को कुछ हिस्सा (जो तुम्हारे मतलब का है वह) तो ज़ाहिर करते हो और बहुतेरे को (जो ख़िलाफ मदआ है) छिपाते हो हालॉकि उसी किताब के ज़रिए से तुम्हें वो बातें सिखायी गयी जिन्हें न तुम जानते थे और न तुम्हारे बाप दादा (ऐ रसूल वह तो जवाब देगें नहीं) तुम ही कह दो कि ख़ुदा ने (नाज़िल फरमाई)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,92,'Al-An''aam','وَهَٰذَا كِتَٰبٌ أَنزَلۡنَٰهُ مُبَارَكࣱ مُّصَدِّقُ ٱلَّذِي بَيۡنَ يَدَيۡهِ وَلِتُنذِرَ أُمَّ ٱلۡقُرَىٰ وَمَنۡ حَوۡلَهَاۚ وَٱلَّذِينَ يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ يُؤۡمِنُونَ بِهِۦۖ وَهُمۡ عَلَىٰ صَلَاتِهِمۡ يُحَافِظُونَ','اور (ویسی ہی) یہ کتاب ہے جسے ہم نے نازل کیا ہے بابرکت جو اپنے سے پہلی (کتابوں) کی تصدیق کرتی ہے اور (جو) اس لئے (نازل کی گئی ہے) کہ تم مکے اور اس کے آس پاس کے لوگوں کو آگاہ کردو۔ اور جو لوگ آخرت پر ایمان رکھتے ہیں وہ اس کتاب پر بھی ایمان رکھتے ہیں اور وہ اپنی نمازوں کی پوری خبر رکھتے ہیں','This is a blessed Book which We have revealed—confirming what came before it—so you may warn the Mother of Cities and everyone around it. Those who believe in the Hereafter ˹truly˺ believe in it and guard their prayers','उसके बाद उन्हें छोड़ के (पडे झक मारा करें (और) अपनी तू तू मै मै में खेलते फिरें और (क़ुरान) भी वह किताब है जिसे हमने बाबरकत नाज़िल किया और उस किताब की तसदीक़ करती है जो उसके सामने (पहले से) मौजूद है और (इस वास्ते नाज़िल किया है) ताकि तुम उसके ज़रिए से अहले मक्का और उसके एतराफ़ के रहने वालों को (ख़ौफ ख़ुदा से) डराओ और जो लोग आख़िरत पर ईमान रखते हैं वह तो उस पर (बे ताम्मुल) ईमान लाते है और वही अपनी अपनी नमाज़ में भी पाबन्दी करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,93,'Al-An''aam','وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ قَالَ أُوحِيَ إِلَيَّ وَلَمۡ يُوحَ إِلَيۡهِ شَيۡءࣱ وَمَن قَالَ سَأُنزِلُ مِثۡلَ مَآ أَنزَلَ ٱللَّهُۗ وَلَوۡ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ فِي غَمَرَٰتِ ٱلۡمَوۡتِ وَٱلۡمَلَٰٓئِكَةُ بَاسِطُوٓاْ أَيۡدِيهِمۡ أَخۡرِجُوٓاْ أَنفُسَكُمُۖ ٱلۡيَوۡمَ تُجۡزَوۡنَ عَذَابَ ٱلۡهُونِ بِمَا كُنتُمۡ تَقُولُونَ عَلَى ٱللَّهِ غَيۡرَ ٱلۡحَقِّ وَكُنتُمۡ عَنۡ ءَايَٰتِهِۦ تَسۡتَكۡبِرُونَ','اور اس سے بڑھ کر ظالم کون ہوگا جو خدا پر جھوٹ افتراء کرے۔ یا یہ کہے کہ مجھ پر وحی آئی ہے حالانکہ اس پر کچھ بھی وحی نہ آئی ہو اور جو یہ کہے کہ جس طرح کی کتاب خدا نے نازل کی ہے اس طرح کی میں بھی بنا لیتا ہوں۔ اور کاش تم ان ظالم (یعنی مشرک) لوگوں کو اس وقت دیکھو جب موت کی سختیوں میں (مبتلا) ہوں اور فرشتے (ان کی طرف عذاب کے لئے) ہاتھ بڑھا رہے ہوں کہ نکالو اپنی جانیں۔ آج تم کو ذلت کے عذاب کی سزا دی جائے گی اس لئے کہ تم خدا پر جھوٹ بولا کرتے تھے اور اس کی آیتوں سے سرکشی کرتے تھے','Who does more wrong than the one who fabricates lies against Allah or claims, “I have received revelations!”—although nothing was revealed to them—or the one who says, “I can reveal the like of Allah’s revelations!”? If you ˹O Prophet˺ could only see the wrongdoers in the throes of death while the angels are stretching out their hands ˹saying˺, “Give up your souls! Today you will be rewarded with the torment of disgrace for telling lies about Allah and for being arrogant towards His revelations!”','और उससे बढ़ कर ज़ालिम कौन होगा जो ख़ुदा पर झूठ (मूठ) इफ़तेरा करके कहे कि हमारे पास वही आयी है हालॉकि उसके पास वही वगैरह कुछ भी नही आयी या वह शख़्श दावा करे कि जैसा क़ुरान ख़ुदा ने नाज़िल किया है वैसा मै भी (अभी) अनक़रीब (जल्दी) नाज़िल किए देता हूँ और (ऐ रसूल) काश तुम देखते कि ये ज़ालिम मौत की सख्तियों में पड़ें हैं और फरिश्ते उनकी तरफ (जान निकाल लेने के वास्ते) हाथ लपका रहे हैं और कहते जाते हैं कि अपनी जानें निकालो आज ही तो तुम को रुसवाई के अज़ाब की सज़ा दी जाएगी क्योंकि तुम ख़ुदा पर नाहक़ (नाहक़) झूठ छोड़ा करते थे और उसकी आयतों को (सुनकर उन) से अकड़ा करते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,94,'Al-An''aam','وَلَقَدۡ جِئۡتُمُونَا فُرَٰدَىٰ كَمَا خَلَقۡنَٰكُمۡ أَوَّلَ مَرَّةࣲ وَتَرَكۡتُم مَّا خَوَّلۡنَٰكُمۡ وَرَآءَ ظُهُورِكُمۡۖ وَمَا نَرَىٰ مَعَكُمۡ شُفَعَآءَكُمُ ٱلَّذِينَ زَعَمۡتُمۡ أَنَّهُمۡ فِيكُمۡ شُرَكَٰٓؤُاْۚ لَقَد تَّقَطَّعَ بَيۡنَكُمۡ وَضَلَّ عَنكُم مَّا كُنتُمۡ تَزۡعُمُونَ','اور جیسا ہم نے تم کو پہلی دفعہ پیدا کیا تھا ایسا ہی آج اکیلے اکیلے ہمارے پاس آئے اور جو (مال ومتاع) ہم نے تمہیں عطا فرمایا تھا وہ سب اپنی پیٹھ پیچھے چھوڑ آئے اور ہم تمہارے ساتھ تمہارے سفارشیوں کو بھی نہیں دیکھتے جن کی نسبت تم خیال کرتے تھے کہ وہ تمہارے (شفیع اور ہمارے) شریک ہیں۔ (آج) تمہارے آپس کے سب تعلقات منقطع ہوگئے اور جو دعوے تم کیا کرتے تھے سب جاتے رہے','˹Today˺ you have come back to Us all alone as We created you the first time—leaving behind everything We have provided you with. We do not see your intercessors with you—those you claimed were Allah’s partners ˹in worship˺. All your ties have been broken and all your claims have let you down.”','और आख़िर तुम हमारे पास इसी तरह तन्हा आए (ना) जिस तरह हमने तुम को पहली बार पैदा किया था और जो (माल व औलाद) हमने तुमको दिया था वह सब अपने पस्त पुश्त (पीछे) छोड़ आए और तुम्हारे साथ तुम्हारे उन सिफारिश करने वालों को भी नहीं देखते जिन को तुम ख्याल करते थे कि वह तुम्हारी (परवरिश वगैरह) मै (हमारे) साझेदार है अब तो तुम्हारे बाहरी ताल्लुक़ात मनक़तआ (ख़त्म) हो गए और जो कुछ ख्याल करते थे वह सब तुम से ग़ायब हो गए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,95,'Al-An''aam','۞إِنَّ ٱللَّهَ فَالِقُ ٱلۡحَبِّ وَٱلنَّوَىٰۖ يُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَمُخۡرِجُ ٱلۡمَيِّتِ مِنَ ٱلۡحَيِّۚ ذَٰلِكُمُ ٱللَّهُۖ فَأَنَّىٰ تُؤۡفَكُونَ','بے شک خدا ہی دانے اور گٹھلی کو پھاڑ کر (ان سے درخت وغیرہ) اگاتا ہے وہی جاندار کو بے جان سے نکالتا ہے اور وہی بےجان کا جاندار سے نکالنے والا ہے۔ یہی تو خدا ہے۔ پھر تم کہاں بہکے پھرتے ہو','Indeed, Allah is the One Who causes seeds and fruit stones to sprout. He brings forth the living from the dead and the dead from the living. That is Allah! How can you then be deluded ˹from the truth˺','ख़ुदा ही तो गुठली और दाने को चीर (करके दरख्त ऊगाता) है वही मुर्दे में से ज़िन्दे को निकालता है और वही ज़िन्दा से मुर्दे को निकालने वाला है (लोगों) वही तुम्हारा ख़ुदा है फिर तुम किधर बहके जा रहे हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,96,'Al-An''aam','فَالِقُ ٱلۡإِصۡبَاحِ وَجَعَلَ ٱلَّيۡلَ سَكَنࣰ ا وَٱلشَّمۡسَ وَٱلۡقَمَرَ حُسۡبَانࣰ اۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ','وہی (رات کے اندھیرے سے) صبح کی روشنی پھاڑ نکالتا ہے اور اسی نے رات کو (موجب) آرام (ٹھہرایا) اور سورج اور چاند کو (ذرائع) شمار بنایا ہے۔ یہ خدا کے (مقرر کئے ہوئے) اندازے ہیں جو غالب (اور) علم والا ہے','He causes the dawn to break, and has made the night for rest and ˹made˺ the sun and the moon ˹to travel˺ with precision. That is the design of the Almighty, All-Knowing','उसी के लिए सुबह की पौ फटी और उसी ने आराम के लिए रात और हिसाब के लिए सूरज और चाँद बनाए ये ख़ुदाए ग़ालिब व दाना के मुक़र्रर किए हुए किरदा (उसूल) हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,97,'Al-An''aam','وَهُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهۡتَدُواْ بِهَا فِي ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمࣲ يَعۡلَمُونَ','اور وہی تو ہے جس نے تمہارے لئے ستارے بنائے تاکہ جنگلوں اور دریاؤں کے اندھیروں میں ان سے رستے معلوم کرو۔ عقل والوں کے لئے ہم نے اپنی آیتیں کھول کھول کر بیان کردی ہیں','And He is the One Who has made the stars as your guide through the darkness of land and sea. We have already made the signs clear for people who know','और वह वही (ख़ुदा) है जिसने तुम्हारे (नफे के) वास्ते सितारे पैदा किए ताकि तुम जॅगलों और दरियाओं की तारिक़ियों (अंधेरों) में उनसे राह मालूम करो जो लोग वाक़िफकार हैं उनके लिए हमने (अपनी क़ुदरत की) निशानियाँ ख़ूब तफ़सील से बयान कर दी हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,98,'Al-An''aam','وَهُوَ ٱلَّذِيٓ أَنشَأَكُم مِّن نَّفۡسࣲ وَٰحِدَةࣲ فَمُسۡتَقَرࣱّ وَمُسۡتَوۡدَعࣱۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمࣲ يَفۡقَهُونَ','اور وہی تو ہے جس نے تم کو ایک شخص سے پیدا کیا۔ پھر (تمہارے لئے) ایک ٹھہرنے کی جگہ ہے اور ایک سپرد ہونے کی سمجھنے والوں کے لئے ہم نے (اپنی) آیتیں کھول کھول کر بیان کردی ہیں','And He is the One Who originated you all from a single soul, then assigned you a place to live and another to ˹be laid to˺ rest. We have already made the signs clear for people who comprehend','और वह वही ख़ुदा है जिसने तुम लोगों को एक शख़्श से पैदा किया फिर (हर शख़्श के) क़रार की जगह (बाप की पुश्त (पीठ)) और सौंपने की जगह (माँ का पेट) मुक़र्रर है हमने समझदार लोगों के वास्ते (अपनी कुदरत की) निशानियाँ ख़ूब तफसील से बयान कर दी हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,99,'Al-An''aam','وَهُوَ ٱلَّذِيٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءࣰ فَأَخۡرَجۡنَا بِهِۦ نَبَاتَ كُلِّ شَيۡءࣲ فَأَخۡرَجۡنَا مِنۡهُ خَضِرࣰ ا نُّخۡرِجُ مِنۡهُ حَبࣰّ ا مُّتَرَاكِبࣰ ا وَمِنَ ٱلنَّخۡلِ مِن طَلۡعِهَا قِنۡوَانࣱ دَانِيَةࣱ وَجَنَّٰتࣲ مِّنۡ أَعۡنَابࣲ وَٱلزَّيۡتُونَ وَٱلرُّمَّانَ مُشۡتَبِهࣰ ا وَغَيۡرَ مُتَشَٰبِهٍۗ ٱنظُرُوٓاْ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثۡمَرَ وَيَنۡعِهِۦٓۚ إِنَّ فِي ذَٰلِكُمۡ لَأٓيَٰتࣲ لِّقَوۡمࣲ يُؤۡمِنُونَ','اور وہی تو ہے جو آسمان سے مینھ برساتا ہے۔ پھر ہم ہی (جو مینھ برساتے ہیں) اس سے ہر طرح کی روئیدگی اگاتے ہیں۔ پھر اس میں سے سبز سبز کونپلیں نکالتے ہیں۔ اور ان کونپلوں میں سے ایک دوسرے کے ساتھ جڑے ہوئے دانے نکالتے ہیں اور کھجور کے گابھے میں سے لٹکتے ہوئے گچھے اور انگوروں کے باغ اور زیتون اور انار جو ایک دوسرے سے ملتے جلتے بھی ہیں۔ اور نہیں بھی ملتے۔ یہ چیزیں جب پھلتی ہیں تو ان کے پھلوں پر اور (جب پکتی ہیں تو) ان کے پکنے پر نظر کرو۔ ان میں ان لوگوں کے لئے جو ایمان لاتے ہیں (قدرت خدا کی بہت سی) نشانیاں ہیں','And He is the One Who sends down rain from the sky—causing all kinds of plants to grow—producing green stalks from which We bring forth clustered grain. And from palm trees come clusters of dates hanging within reach. ˹There are˺ also gardens of grapevines, olives, and pomegranates, similar ˹in shape˺ but dissimilar ˹in taste˺. Look at their fruit as it yields and ripens! Indeed, in these are signs for people who believe','और वह वही (क़ादिर तवाना है) जिसने आसमान से पानी बरसाया फिर हम ही ने उसके ज़रिए से हर चीज़ के कोए निकालें फिर हम ही ने उससे हरी भरी टहनियाँ निकालीं कि उससे हम बाहम गुत्थे दाने निकालते हैं और छुहारे के बोर (मुन्जिर) से लटके हुए गुच्छे पैदा किए और अंगूर और ज़ैतून और अनार के बाग़ात जो बाहम सूरत में एक दूसरे से मिलते जुलते और (मजे में) जुदा जुदा जब ये पिघले और पक्के तो उसके फल की तरफ ग़ौर तो करो बेशक अमन में ईमानदार लोगों के लिए बहुत सी (ख़ुदा की) निशानियाँ हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,100,'Al-An''aam','وَجَعَلُواْ لِلَّهِ شُرَكَآءَ ٱلۡجِنَّ وَخَلَقَهُمۡۖ وَخَرَقُواْ لَهُۥ بَنِينَ وَبَنَٰتِۭ بِغَيۡرِ عِلۡمࣲۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَصِفُونَ','اور ان لوگوں نے جنوں کو خدا کا شریک ٹھہرایا۔ حالانکہ ان کو اسی نے پیدا کیا اور بےسمجھے (جھوٹ بہتان) اس کے لئے بیٹے اور بیٹیاں بنا کھڑی کیں وہ ان باتوں سے جو اس کی نسبت بیان کرتے ہیں پاک ہے اور (اس کی شان ان سے) بلند ہے','Yet they associate the jinn with Allah ˹in worship˺, even though He created them, and they falsely attribute to Him sons and daughters out of ignorance. Glorified and Exalted is He above what they claim','और उन (कम्बख्तों) ने जिन्नात को ख़ुदा का शरीक बनाया हालॉकि जिन्नात को भी ख़ुदा ही ने पैदा किया उस पर भी उन लोगों ने बे समझे बूझे ख़ुदा के लिए बेटे बेटियाँ गढ़ डालीं जो बातों में लोग (उसकी शान में) बयान करते हैं उससे वह पाक व पाकीज़ा और बरतर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,101,'Al-An''aam','بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ أَنَّىٰ يَكُونُ لَهُۥ وَلَدࣱ وَلَمۡ تَكُن لَّهُۥ صَٰحِبَةࣱۖ وَخَلَقَ كُلَّ شَيۡءࣲۖ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمࣱ‏','(وہی) آسمانوں اور زمین کا پیدا کرنے والا (ہے) ۔ اس کے اولاد کہاں سے ہو جب کہ اس کی بیوی ہی نہیں۔ اور اس نے ہر چیز کو پیدا کیا ہے۔ اور وہ ہر چیز سے باخبر ہے','˹He is˺ the Originator of the heavens and earth. How could He have children when He has no mate? He created all things and has ˹perfect˺ knowledge of everything','सारे आसमान और ज़मीन का मवविद (बनाने वाला) है उसके कोई लड़का क्योंकर हो सकता है जब उसकी कोई बीबी ही नहीं है और उसी ने हर चीज़ को पैदा किया और वही हर चीज़ से खूब वाक़िफ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,102,'Al-An''aam','ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡۖ لَآ إِلَٰهَ إِلَّا هُوَۖ خَٰلِقُ كُلِّ شَيۡءࣲ فَٱعۡبُدُوهُۚ وَهُوَ عَلَىٰ كُلِّ شَيۡءࣲ وَكِيلࣱ‏','یہی (اوصاف رکھنے والا) خدا تمہارا پروردگار ہے۔ اس کے سوا کوئی معبود نہیں۔ (وہی) ہر چیز کا پیداکرنے والا (ہے) تو اسی کی عبادت کرو۔ اور وہ ہر چیز کا نگراں ہے','That is Allah—your Lord! There is no god ˹worthy of worship˺ except Him. ˹He is˺ the Creator of all things, so worship Him ˹alone˺. And He is the Maintainer of everything','(लोगों) वही अल्लाह तुम्हारा परवरदिगार है उसके सिवा कोई माबूद नहीं वही हर चीज़ का पैदा करने वाला है तो उसी की इबादत करो और वही हर चीज़ का निगेह बान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,103,'Al-An''aam','لَّا تُدۡرِكُهُ ٱلۡأَبۡصَٰرُ وَهُوَ يُدۡرِكُ ٱلۡأَبۡصَٰرَۖ وَهُوَ ٱللَّطِيفُ ٱلۡخَبِيرُ','(وہ ایسا ہے کہ) نگاہیں اس کا ادراک نہیں کرسکتیں اور وہ نگاہوں کا ادراک کرسکتا ہے اور وہ بھید جاننے والا خبردار ہے','No vision can encompass Him, but He encompasses all vision. For He is the Most Subtle, All-Aware','उसको ऑंखें देख नहीं सकती (न दुनिया में न आख़िरत में) और वह (लोगों की) नज़रों को खूब देखता है और वह बड़ा बारीक बीन (देख़ने वाला) ख़बरदार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,104,'Al-An''aam','قَدۡ جَآءَكُم بَصَآئِرُ مِن رَّبِّكُمۡۖ فَمَنۡ أَبۡصَرَ فَلِنَفۡسِهِۦۖ وَمَنۡ عَمِيَ فَعَلَيۡهَاۚ وَمَآ أَنَا۠ عَلَيۡكُم بِحَفِيظࣲ‏','(اے محمدﷺ! ان سے کہہ دو کہ) تمہارے (پاس) پروردگار کی طرف سے (روشن) دلیلیں پہنچ چکی ہیں تو جس نے (ان کو آنکھ کھول کر) دیکھا اس نے اپنا بھلا کیا اور جو اندھا بنا رہا اس نے اپنے حق میں برا کیا۔ اور میں تمہارا نگہبان نہیں ہوں','Indeed, there have come to you insights from your Lord. So whoever chooses to see, it is for their own good. But whoever chooses to be blind, it is to their own loss. And I am not a keeper over you','तुम्हारे पास तो सुझाने वाली चीज़े आ ही चुकीं फिर जो देखे (समझे) तो अपने दम के लिए और जो अन्धा बने तो (उसका ज़रर (नुकसान) भी) ख़ुद उस पर है और (ऐ रसूल उन से कह दो) कि मै तुम लोगों का कुछ निगेहबान तो हूँ नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,105,'Al-An''aam','وَكَذَٰلِكَ نُصَرِّفُ ٱلۡأٓيَٰتِ وَلِيَقُولُواْ دَرَسۡتَ وَلِنُبَيِّنَهُۥ لِقَوۡمࣲ يَعۡلَمُونَ','اور ہم اسی طرح اپنی آیتیں پھیر پھیر کر بیان کرتے ہیں تاکہ کافر یہ نہ کہیں کہ تم (یہ باتیں اہل کتاب سے) سیکھے ہوئے ہو اور تاکہ سمجھنے والے لوگوں کے لئے تشریح کردیں','And so We vary our signs to the extent that they will say, “You have studied ˹previous scriptures˺,” and We make this ˹Quran˺ clear for people who know','और हम (अपनी) आयतें यूं उलट फेरकर बयान करते है (ताकि हुज्जत तमाम हो) और ताकि वह लोग ज़बानी भी इक़रार कर लें कि तुमने (क़ुरान उनके सामने) पढ़ दिया और ताकि जो लोग जानते है उनके लिए (क़ुरान का) खूब वाजेए करके बयान कर दें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,106,'Al-An''aam','ٱتَّبِعۡ مَآ أُوحِيَ إِلَيۡكَ مِن رَّبِّكَۖ لَآ إِلَٰهَ إِلَّا هُوَۖ وَأَعۡرِضۡ عَنِ ٱلۡمُشۡرِكِينَ','اور جو حکم تمہارے پروردگار کی طرف سے تمہارے پاس آتا ہے اسی کی پیروی کرو۔ اس (پروردگار) کے سوا کوئی معبود نہیں۔ اور مشرکوں سے کنارہ کرلو','˹O Prophet!˺ Follow what is revealed to you from your Lord—there is no god ˹worthy of worship˺ except Him—and turn away from the polytheists','जो कुछ तुम्हारे पास तुम्हारे परवरदिगार की तरफ से ''वही'' की जाए बस उसी पर चलो अल्लाह के सिवा कोई माबूद नहीं और मुशरिको से किनारा कश रहो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,107,'Al-An''aam','وَلَوۡ شَآءَ ٱللَّهُ مَآ أَشۡرَكُواْۗ وَمَا جَعَلۡنَٰكَ عَلَيۡهِمۡ حَفِيظࣰ اۖ وَمَآ أَنتَ عَلَيۡهِم بِوَكِيلࣲ‏','اور اگر خدا چاہتا تو یہ لوگ شرک نہ کرتے۔ اور (اے پیغمبر!) ہم نے تم کو ان پر نگہبان مقرر نہیں کیا۔ اور نہ تم ان کے داروغہ ہو','Had Allah willed, they would not have been polytheists. We have not appointed you as their keeper, nor are you their maintainer','और अगर ख़ुदा चाहता तो ये लोग शिर्क ही न करते और हमने तुमको उन लोगों का निगेहबान तो बनाया नहीं है और न तुम उनके ज़िम्मेदार हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,108,'Al-An''aam','وَلَا تَسُبُّواْ ٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّواْ ٱللَّهَ عَدۡوَۢا بِغَيۡرِ عِلۡمࣲۗ كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمۡ ثُمَّ إِلَىٰ رَبِّهِم مَّرۡجِعُهُمۡ فَيُنَبِّئُهُم بِمَا كَانُواْ يَعۡمَلُونَ','اور جن لوگوں کو یہ مشرک خدا کے سوا پکارتے ہیں ان کو برا نہ کہنا کہ یہ بھی کہیں خدا کو بےادبی سے بے سمجھے برا (نہ) کہہ بیٹھیں۔ اس طرح ہم نے ہر ایک فرقے کے اعمال (ان کی نظروں میں) اچھے کر دکھائے ہیں۔ پھر ان کو اپنے پروردگار ک طرف لوٹ کر جانا ہے تب وہ ان کو بتائے گا کہ وہ کیا کیا کرتے تھے','˹O believers!˺ Do not insult what they invoke besides Allah or they will insult Allah spitefully out of ignorance. This is how We have made each people’s deeds appealing to them. Then to their Lord is their return, and He will inform them of what they used to do','और ये (मुशरेकीन) जिन की अल्लाह के सिवा (ख़ुदा समझ कर) इबादत करते हैं उन्हें तुम बुरा न कहा करो वरना ये लोग भी ख़ुदा को बिना समझें अदावत से बुरा (भला) कह बैठें (और लोग उनकी ख्वाहिश नफसानी के) इस तरह पाबन्द हुए कि गोया हमने ख़ुद हर गिरोह के आमाल उनको सॅवाकर अच्छे कर दिखाए फिर उन्हें तो (आख़िरकार) अपने परवरदिगार की तरफ लौट कर जाना है तब जो कुछ दुनिया में कर रहे थे ख़ुदा उन्हें बता देगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,109,'Al-An''aam','وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِن جَآءَتۡهُمۡ ءَايَةࣱ لَّيُؤۡمِنُنَّ بِهَاۚ قُلۡ إِنَّمَا ٱلۡأٓيَٰتُ عِندَ ٱللَّهِۖ وَمَا يُشۡعِرُكُمۡ أَنَّهَآ إِذَا جَآءَتۡ لَا يُؤۡمِنُونَ','اور یہ لوگ خدا کی سخت سخت قسمیں کھاتے ہیں کہ اگر ان کے پاس کوئی نشانی آئے تو وہ اس پر ضروری ایمان لے آئیں۔ کہہ دو کہ نشانیاں تو سب خدا ہی کے پاس ہیں۔ اور (مومنو!) تمہیں کیا معلوم ہے (یہ تو ایسے بدبخت ہیں کہ ان کے پاس) نشانیاں آ بھی جائیں تب بھی ایمان نہ لائیں','They swear by Allah their most solemn oaths that if a sign were to come to them, they would certainly believe in it. Say, ˹O Prophet,˺ “Signs are only with Allah.” What will make you ˹believers˺ realize that even if a sign were to come to them, they still would not believe','और उन लोगों ने ख़ुदा की सख्त सख्त क़समें खायीं कि अगर उनके पास कोई मौजिजा आए तो वह ज़रूर उस पर ईमान लाएँगे (ऐ रसूल) तुम कहो कि मौजिज़े तो बस ख़ुदा ही के पास हैं और तुम्हें क्या मालूम ये यक़ीनी बात है कि जब मौजिज़ा भी आएगा तो भी ये ईमान न लाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,110,'Al-An''aam','وَنُقَلِّبُ أَفۡـِٔدَتَهُمۡ وَأَبۡصَٰرَهُمۡ كَمَا لَمۡ يُؤۡمِنُواْ بِهِۦٓ أَوَّلَ مَرَّةࣲ وَنَذَرُهُمۡ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ','اور ہم ان کے دلوں اور آنکھوں کو الٹ دیں گے (تو) جیسے یہ اس (قرآن) پر پہلی دفعہ ایمان نہیں لائے (ویسے پھر نہ لائیں گے) اور ان کو چھوڑ دیں گے کہ اپنی سرکشی میں بہکتے رہیں','We turn their hearts and eyes away ˹from the truth˺ as they refused to believe at first, leaving them to wander blindly in their defiance','और हम उनके दिल और उनकी ऑंखें उलट पलट कर देंगे जिस तरह ये लोग कुरान पर पहली मरतबा ईमान न लाए और हम उन्हें उनकी सरकशी की हालत में छोड़ देंगे कि सरगिरदाँ (परेशान) रहें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,111,'Al-An''aam','۞وَلَوۡ أَنَّنَا نَزَّلۡنَآ إِلَيۡهِمُ ٱلۡمَلَٰٓئِكَةَ وَكَلَّمَهُمُ ٱلۡمَوۡتَىٰ وَحَشَرۡنَا عَلَيۡهِمۡ كُلَّ شَيۡءࣲ قُبُلࣰ ا مَّا كَانُواْ لِيُؤۡمِنُوٓاْ إِلَّآ أَن يَشَآءَ ٱللَّهُ وَلَٰكِنَّ أَكۡثَرَهُمۡ يَجۡهَلُونَ','اور اگر ہم ان پر فرشتے بھی اتار دیتے اور مردے بھی ان سے گفتگو کرنے لگتے اور ہم سب چیزوں کو ان کے سامنے لا موجود بھی کر دیتے تو بھی یہ ایمان لانے والے نہ تھے اِلّا ماشائالله بات یہ ہے کہ یہ اکثر نادان ہیں','Even if We had sent them the angels, made the dead speak to them, and assembled before their own eyes every sign ˹they demanded˺, they still would not have believed—unless Allah so willed. But most of them are ignorant ˹of this˺','और (ऐ रसूल सच तो ये है कि) हम अगर उनके पास फरिश्ते भी नाज़िल करते और उनसे मुर्दे भी बातें करने लगते और तमाम (मख़फ़ी(छुपी)) चीज़ें (जैसे जन्नत व नार वग़ैरह) अगर वह गिरोह उनके सामने ला खड़े करते तो भी ये ईमान लाने वाले न थे मगर जब अल्लाह चाहे लेकिन उनमें के अक्सर नहीं जानते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,112,'Al-An''aam','وَكَذَٰلِكَ جَعَلۡنَا لِكُلِّ نَبِيٍّ عَدُوࣰّ ا شَيَٰطِينَ ٱلۡإِنسِ وَٱلۡجِنِّ يُوحِي بَعۡضُهُمۡ إِلَىٰ بَعۡضࣲ زُخۡرُفَ ٱلۡقَوۡلِ غُرُورࣰ اۚ وَلَوۡ شَآءَ رَبُّكَ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا يَفۡتَرُونَ','اور اسی طرح ہم نے شیطان (سیرت) انسانوں اور جنوں کو ہر پیغمبر کا دشمن بنا دیا تھا وہ دھوکا دینے کے لیے ایک دوسرے کے دل میں ملمع کی باتیں ڈالتے رہتے تھے اور اگر تمہارا پروردگار چاہتا تو وہ ایسا نہ کرتے تو ان کو اور جو کچھ یہ افتراء کرتے ہیں اسے چھوڑ دو','And so We have made for every prophet enemies—devilish humans and jinn—whispering to one another with elegant words of deception. Had it been your Lord’s Will, they would not have done such a thing. So leave them and their deceit','कि और (ऐ रसूल जिस तरह ये कुफ्फ़ार तुम्हारे दुश्मन हैं) उसी तरह (गोया हमने ख़ुद आज़माइश के लिए शरीर आदमियों और जिनों को हर नबी का दुश्मन बनाया वह लोग एक दूसरे को फरेब देने की ग़रज़ से चिकनी चुपड़ी बातों की सरग़ोशी करते हैं और अगर तुम्हारा परवरदिगार चाहता तो ये लोग) ऐसी हरकत करने न पाते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,113,'Al-An''aam','وَلِتَصۡغَىٰٓ إِلَيۡهِ أَفۡـِٔدَةُ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ وَلِيَرۡضَوۡهُ وَلِيَقۡتَرِفُواْ مَا هُم مُّقۡتَرِفُونَ','اور (وہ ایسے کام) اس لیے بھی (کرتے تھے) کہ جو لوگ آخرت پر ایمان نہیں رکھتے ان کے دل ان کی باتوں پر مائل ہوں اور وہ انہیں پسند کریں اور جو کام وہ کرتے تھے وہ ہی کرنے لگیں','so that the hearts of those who disbelieve in the Hereafter may be receptive to it, be pleased with it, and be persistent in their evil pursuits','तो उनको और उनकी इफ़तेरा परदाज़ियों को छोड़ दो और ये (ये सरग़ोशियाँ इसलिए थीं) ताकि जो लोग आख़िरत पर ईमान नहीं लाए उनके दिल उन (की शरारत) की तरफ मायल (ख्ािंच) हो जाएँ और उन्हें पसन्द करें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,114,'Al-An''aam','أَفَغَيۡرَ ٱللَّهِ أَبۡتَغِي حَكَمࣰ ا وَهُوَ ٱلَّذِيٓ أَنزَلَ إِلَيۡكُمُ ٱلۡكِتَٰبَ مُفَصَّلࣰ اۚ وَٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡلَمُونَ أَنَّهُۥ مُنَزَّلࣱ مِّن رَّبِّكَ بِٱلۡحَقِّۖ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ','(کہو) کیا میں خدا کے سوا اور منصف تلاش کروں حالانکہ اس نے تمہاری طرف واضع المطالب کتاب بھیجی ہے اور جن لوگوں کو ہم نے کتاب (تورات) دی ہے وہ جانتے ہیں کہ وہ تمہارے پروردگار کی طرف سے برحق نازل ہوئی ہے تو تم ہرگز شک کرنے والوں میں نہ ہونا','˹Say, O Prophet,˺ “Should I seek a judge other than Allah while He is the One Who has revealed for you the Book ˹with the truth˺ perfectly explained?” Those who were given the Scripture know that it has been revealed ˹to you˺ from your Lord in truth. So do not be one of those who doubt','और ताकि जो लोग इफ़तेरा परदाज़ियाँ ये लोग ख़ुद करते हैं वह भी करने लगें (क्या तुम ये चाहते हो कि) मैं ख़ुदा को छोड़ कर किसी और को सालिस तलाश करुँ हालॉकि वह वही ख़ुदा है जिसने तुम्हारे पास वाज़ेए किताब नाज़िल की और जिन लोगों को हमने किताब अता फरमाई है वह यक़ीनी तौर पर जानते हैं कि ये (कुरान भी) तुम्हारे परवरदिगार की तरफ से बरहक़ नाज़िल किया गया है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,115,'Al-An''aam','وَتَمَّتۡ كَلِمَتُ رَبِّكَ صِدۡقࣰ ا وَعَدۡلࣰ اۚ لَّا مُبَدِّلَ لِكَلِمَٰتِهِۦۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ','اور تمہارے پروردگار کی باتیں سچائی اور انصاف میں پوری ہیں اس کی باتوں کو کوئی بدلنے والا نہیں اور وہ سنتا جانتا ہے','The Word of your Lord has been perfected in truth and justice. None can change His Words. And He is the All-Hearing, All- Knowing','तो तुम (कहीं) शक़ करने वालों से न हो जाना और सच्चाई और इन्साफ में तो तुम्हारे परवरदिगार की बात पूरी हो गई कोई उसकी बातों का बदलने वाला नहीं और वही बड़ा सुनने वाला वाक़िफकार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,116,'Al-An''aam','وَإِن تُطِعۡ أَكۡثَرَ مَن فِي ٱلۡأَرۡضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ هُمۡ إِلَّا يَخۡرُصُونَ','اور اکثر لوگ جو زمین پر آباد ہیں (گمراہ ہیں) اگر تم ان کا کہا مان لو گے تو وہ تمہیں خدا کا رستہ بھلا دیں گے یہ محض خیال کے پیچھے چلتے اور نرے اٹکل کے تیر چلاتے ہیں','˹O Prophet!˺ If you were to obey most of those on earth, they would lead you away from Allah’s Way. They follow nothing but assumptions and do nothing but lie','और (ऐ रसूल) दुनिया में तो बहुतेरे लोग ऐसे हैं कि तुम उनके कहने पर चलो तो तुमको ख़ुदा की राह से बहका दें ये लोग तो सिर्फ अपने ख्यालात की पैरवी करते हैं और ये लोग तो बस अटकल पच्चू बातें किया करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,117,'Al-An''aam','إِنَّ رَبَّكَ هُوَ أَعۡلَمُ مَن يَضِلُّ عَن سَبِيلِهِۦۖ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ','تمہارا پروردگار ان لوگوں کو خوب جانتا ہے جو اس کے رستے سے بھٹکے ہوئے ہیں اور ان سے بھی خوب واقف ہے جو رستے پر چل رہے ہیں','Indeed, your Lord knows best who has strayed from His Way and who is ˹rightly˺ guided','(तो तुम क्या जानों) जो लोग उसकी राह से बहके हुए हैं उनको (कुछ) ख़ुदा ही ख़ूब जानता है और वह तो हिदायत याफ्ता लोगों से भी ख़ूब वाक़िफ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,118,'Al-An''aam','فَكُلُواْ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَيۡهِ إِن كُنتُم بِـَٔايَٰتِهِۦ مُؤۡمِنِينَ','تو جس چیز پر (ذبح کے وقت) خدا کا نام لیا جائے اگر تم اس کی آیتوں پر ایمان رکھتے ہو تو اسے کھا لیا کرو','So eat only of what is slaughtered in Allah’s Name if you truly believe in His revelations','तो अगर तुम उसकी आयतों पर ईमान रखते हो तो जिस ज़ीबह पर (वक्ते ़ज़िबाह) ख़ुदा का नाम लिया गया हो उसी को खाओ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,119,'Al-An''aam','وَمَا لَكُمۡ أَلَّا تَأۡكُلُواْ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَيۡهِ وَقَدۡ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيۡكُمۡ إِلَّا مَا ٱضۡطُرِرۡتُمۡ إِلَيۡهِۗ وَإِنَّ كَثِيرࣰ ا لَّيُضِلُّونَ بِأَهۡوَآئِهِم بِغَيۡرِ عِلۡمٍۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِٱلۡمُعۡتَدِينَ','اور سبب کیا ہے کہ جس چیز پر خدا کا نام لیا جائے تم اسے نہ کھاؤ حالانکہ جو چیزیں اس نے تمہارے لیے حرام ٹھیرا دی ہیں وہ ایک ایک کر کے بیان کر دی ہیں (بے شک ان کو نہیں کھانا چاہیے) مگر اس صورت میں کہ ان کے (کھانے کے) لیے ناچار ہو جاؤ اور بہت سے لوگ بےسمجھے بوجھے اپنے نفس کی خواہشوں سے لوگوں کو بہکا رہے ہیں کچھ شک نہیں کہ ایسے لوگوں کو جو (خدا کی مقرر کی ہوئی) حد سے باہر نکل جاتے ہیں تمہارا پروردگار خوب جانتا ہے','Why should you not eat of what is slaughtered in Allah’s Name when He has already explained to you what He has forbidden to you—except when compelled by necessity? Many ˹deviants˺ certainly mislead others by their whims out of ignorance. Surely your Lord knows the transgressors best','और तुम्हें क्या हो गया है कि जिस पर ख़ुदा का नाम लिया गया हो उसमें नहीं खाते हो हालॉकि जो चीज़ें उसने तुम पर हराम कर दीं हैं वह तुमसे तफसीलन बयान कर दीं हैं मगर (हाँ) जब तुम मजबूर हो तो अलबत्ता (हराम भी खा सकते हो) और बहुतेरे तो (ख्वाहमख्वाह) अपनी नफसानी ख्वाहिशों से बे समझे बूझे (लोगों को) बहका देते हैं और तुम्हारा परवरदिगार तो हक़ से तजाविज़ करने वालों से ख़ूब वाक़िफ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,120,'Al-An''aam','وَذَرُواْ ظَٰهِرَ ٱلۡإِثۡمِ وَبَاطِنَهُۥٓۚ إِنَّ ٱلَّذِينَ يَكۡسِبُونَ ٱلۡإِثۡمَ سَيُجۡزَوۡنَ بِمَا كَانُواْ يَقۡتَرِفُونَ','اور ظاہری اور پوشیدہ (ہر طرح کا) گناہ ترک کر دو جو لوگ گناہ کرتے ہیں وہ عنقریب اپنے کئے کی سزا پائیں گے','Shun all sin—open and secret. Indeed, those who commit sin will be punished for what they earn','(ऐ लोगों) ज़ाहिरी और बातिनी गुनाह (दोनों) को (बिल्कुल) छोड़ दो जो लोग गुनाह करते हैं उन्हें अपने आमाल का अनक़रीब ही बदला दिया जाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,121,'Al-An''aam','وَلَا تَأۡكُلُواْ مِمَّا لَمۡ يُذۡكَرِ ٱسۡمُ ٱللَّهِ عَلَيۡهِ وَإِنَّهُۥ لَفِسۡقࣱۗ وَإِنَّ ٱلشَّيَٰطِينَ لَيُوحُونَ إِلَىٰٓ أَوۡلِيَآئِهِمۡ لِيُجَٰدِلُوكُمۡۖ وَإِنۡ أَطَعۡتُمُوهُمۡ إِنَّكُمۡ لَمُشۡرِكُونَ','اور جس چیز پر خدا کا نام نہ لیا جائے اسے مت کھاؤ کہ اس کا کھانا گناہ ہے اور شیطان (لوگ) اپنے رفیقوں کے دلوں میں یہ بات ڈالتے ہیں کہ تم سے جھگڑا کریں اور اگر تم لوگ ان کے کہے پر چلے تو بےشک تم بھی مشرک ہوئے','Do not eat of what is not slaughtered in Allah’s Name. For that would certainly be ˹an act of˺ disobedience. Surely the devils whisper to their ˹human˺ associates to argue with you. If you were to obey them, then you ˹too˺ would be polytheists','और जिस (ज़बीहे) पर ख़ुदा का नाम न लिया गया उसमें से मत खाओ (क्योंकि) ये बेशक बदचलनी है और शयातीन तो अपने हवा ख़वाहों के दिल में वसवसा डाला ही करते हैं ताकि वह तुमसे (बेकार) झगड़े किया करें और अगर (कहीं) तुमने उनका कहना मान लिया तो (समझ रखो कि) बेशुबहा तुम भी मुशरिक हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,122,'Al-An''aam','أَوَمَن كَانَ مَيۡتࣰ ا فَأَحۡيَيۡنَٰهُ وَجَعَلۡنَا لَهُۥ نُورࣰ ا يَمۡشِي بِهِۦ فِي ٱلنَّاسِ كَمَن مَّثَلُهُۥ فِي ٱلظُّلُمَٰتِ لَيۡسَ بِخَارِجࣲ مِّنۡهَاۚ كَذَٰلِكَ زُيِّنَ لِلۡكَٰفِرِينَ مَا كَانُواْ يَعۡمَلُونَ','بھلا جو پہلے مردہ تھا پھر ہم نے اس کو زندہ کیا اور اس کے لیے روشنی کر دی جس کے ذریعے سے وہ لوگوں میں چلتا پھرتا ہے کہیں اس شخص جیسا ہو سکتا ہے جو اندھیرے میں پڑا ہوا ہو اور اس سے نکل ہی نہ سکے اسی طرح کافر جو عمل کر رہے ہیں وہ انہیں اچھے معلوم ہوتے ہیں','Can those who had been dead, to whom We gave life and a light with which they can walk among people, be compared to those in complete darkness from which they can never emerge? That is how the misdeeds of the disbelievers have been made appealing to them','क्या जो शख़्श (पहले) मुर्दा था फिर हमने उसको ज़िन्दा किया और उसके लिए एक नूर बनाया जिसके ज़रिए वह लोगों में (बेतकल्लुफ़) चलता फिरता है उस शख़्श का सामना हो सकता है जिसकी ये हालत है कि (हर तरफ से) अंधेरे में (फँसा हुआ है) कि वहाँ से किसी तरह निकल नहीं सकता (जिस तरह मोमिनों के वास्ते ईमान आरास्ता किया गया) उसी तरह काफिरों के वास्ते उनके आमाल (बद) आरास्ता कर दिए गए हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,123,'Al-An''aam','وَكَذَٰلِكَ جَعَلۡنَا فِي كُلِّ قَرۡيَةٍ أَكَٰبِرَ مُجۡرِمِيهَا لِيَمۡكُرُواْ فِيهَاۖ وَمَا يَمۡكُرُونَ إِلَّا بِأَنفُسِهِمۡ وَمَا يَشۡعُرُونَ','اور اسی طرح ہم نے ہر بستی میں بڑے بڑے مجرم پیدا کئے کہ ان میں مکاریاں کرتے رہیں اور جو مکاریاں یہ کرتے ہیں ان کا نقصان انہیں کو ہے اور (اس سے) بےخبر ہیں','And so We have placed in every society the most wicked to conspire in it. Yet they plot only against themselves, but they fail to perceive it','(कि भला ही भला नज़र आता है) और जिस तरह मक्के में है उसी तरह हमने हर बस्ती में उनके कुसूरवारों को सरदार बनाया ताकि उनमें मक्कारी किया करें और वह लोग जो कुछ करते हैं अपने ही हक़ में (बुरा) करते हैं और समझते (तक) नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,124,'Al-An''aam','وَإِذَا جَآءَتۡهُمۡ ءَايَةࣱ قَالُواْ لَن نُّؤۡمِنَ حَتَّىٰ نُؤۡتَىٰ مِثۡلَ مَآ أُوتِيَ رُسُلُ ٱللَّهِۘ ٱللَّهُ أَعۡلَمُ حَيۡثُ يَجۡعَلُ رِسَالَتَهُۥۗ سَيُصِيبُ ٱلَّذِينَ أَجۡرَمُواْ صَغَارٌ عِندَ ٱللَّهِ وَعَذَابࣱ شَدِيدُۢ بِمَا كَانُواْ يَمۡكُرُونَ','اور جب ان کے پاس کوئی آیت آتی ہے تو کہتے ہیں کہ جس طرح کی رسالت خدا کے پیغمبروں کو ملی ہے جب تک اسی طرح کی رسالت ہم کو نہ ملے ہم ہرگز ایمان نہیں لائیں گے اس کو خدا ہی خوب جانتا ہے کہ (رسالت کا کون سا محل ہے اور) وہ اپنی پیغمبری کسے عنایت فرمائے جو لوگ جرم کرتے ہیں ان کو خدا کے ہاں ذلّت اور عذابِ شدید ہوگا اس لیے کہ مکّاریاں کرتے تھے','Whenever a sign comes to them, they say, “We will never believe until we receive what Allah’s messengers received.” Allah knows best where to place His message. The wicked will soon be overwhelmed by humiliation from Allah and a severe punishment for their evil plots','और जब उनके पास कोई निशानी (नबी की तसदीक़ के लिए) आई है तो कहते हैं जब तक हमको ख़ुद वैसी चीज़ (वही वग़ैरह) न दी जाएगी जो पैग़म्बराने ख़ुदा को दी गई है उस वक्त तक तो हम ईमान न लाएँगे और ख़ुदा जहाँ (जिस दिल में) अपनी पैग़म्बरी क़रार देता है उसकी (काबलियत व सलाहियत) को ख़ूब जानता है जो लोग (उस जुर्म के) मुजरिम हैं उनको अनक़रीब उनकी मक्कारी की सज़ा में ख़ुदा के यहाँ बड़ी ज़िल्लत और सख्त अज़ाब होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,125,'Al-An''aam','فَمَن يُرِدِ ٱللَّهُ أَن يَهۡدِيَهُۥ يَشۡرَحۡ صَدۡرَهُۥ لِلۡإِسۡلَٰمِۖ وَمَن يُرِدۡ أَن يُضِلَّهُۥ يَجۡعَلۡ صَدۡرَهُۥ ضَيِّقًا حَرَجࣰ ا كَأَنَّمَا يَصَّعَّدُ فِي ٱلسَّمَآءِۚ كَذَٰلِكَ يَجۡعَلُ ٱللَّهُ ٱلرِّجۡسَ عَلَى ٱلَّذِينَ لَا يُؤۡمِنُونَ','تو جس شخص کو خدا چاہتا ہے کہ ہدایت بخشے اس کا سینہ اسلام کے لیے کھول دیتا ہے اور جسے چاہتا ہے کہ گمراہ کرے اس کا سینہ تنگ اور گھٹا ہوا کر دیتا ہے گویا وہ آسمان پر چڑھ رہا ہے اس طرح خدا ان لوگوں پر جو ایمان نہیں لاتے عذاب بھیجتا ہے','Whoever Allah wills to guide, He opens their heart to Islam. But whoever He wills to leave astray, He makes their chest tight and constricted as if they were climbing up into the sky. This is how Allah dooms those who disbelieve','तो ख़ुदा जिस शख़्श को राह रास्त दिखाना चाहता है उसके सीने को इस्लाम (की दौलियत) के वास्ते (साफ़ और) कुशादा (चौड़ा) कर देता है और जिसको गुमराही की हालत में छोड़ना चाहता है उनके सीने को तंग दुश्वार ग़ुबार कर देता है गोया (कुबूल ईमान) उसके लिए आसमान पर चढ़ना है जो लोग ईमान नहीं लाते ख़ुदा उन पर बुराई को उसी तरह मुसल्लत कर देता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,126,'Al-An''aam','وَهَٰذَا صِرَٰطُ رَبِّكَ مُسۡتَقِيمࣰ اۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمࣲ يَذَّكَّرُونَ','اور یہی تمہارے پروردگار کا سیدھا رستہ ہے جو لوگ غور کرنے والے ہیں ان کے لیے ہم نے اپنی آیتیں کھول کھول کر بیان کر دی ہیں','That is your Lord’s Path—perfectly straight. We have already made the signs clear to those who are mindful','और (ऐ रसूल) ये (इस्लाम) तुम्हारे परवरदिगार का (बनाया हुआ) सीधा रास्ता है इबरत हासिल करने वालों के वास्ते हमने अपने आयात तफसीलन बयान कर दिए हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,127,'Al-An''aam','۞لَهُمۡ دَارُ ٱلسَّلَٰمِ عِندَ رَبِّهِمۡۖ وَهُوَ وَلِيُّهُم بِمَا كَانُواْ يَعۡمَلُونَ','ان کے لیے ان کے اعمال کے صلے میں پروردگار کے ہاں سلامتی کا گھر ہے اور وہی ان کا دوستدار ہے','They will have the Home of Peace with their Lord, Who will be their Guardian because of what they used to do','उनके वास्ते उनके परवरदिगार के यहाँ अमन व चैन का घर (बेहश्त) है और दुनिया में जो कारगुज़ारियाँ उन्होने की थीं उसके ऐवज़ ख़ुदा उन का सरपरस्त होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,128,'Al-An''aam','وَيَوۡمَ يَحۡشُرُهُمۡ جَمِيعࣰ ا يَٰمَعۡشَرَ ٱلۡجِنِّ قَدِ ٱسۡتَكۡثَرۡتُم مِّنَ ٱلۡإِنسِۖ وَقَالَ أَوۡلِيَآؤُهُم مِّنَ ٱلۡإِنسِ رَبَّنَا ٱسۡتَمۡتَعَ بَعۡضُنَا بِبَعۡضࣲ وَبَلَغۡنَآ أَجَلَنَا ٱلَّذِيٓ أَجَّلۡتَ لَنَاۚ قَالَ ٱلنَّارُ مَثۡوَىٰكُمۡ خَٰلِدِينَ فِيهَآ إِلَّا مَا شَآءَ ٱللَّهُۚ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمࣱ‏','اور جس دن وہ سب (جنّ وانس) کو جمع کرے گا (اور فرمائے گا کہ) اے گروہ جنّات تم نے انسانوں سے بہت (فائدے) حاصل کئے تو جو انسانوں میں ان کے دوستدار ہوں گے وہ کہیں گے کہ پروردگار ہم ایک دوسرے سے فائدہ اٹھاتے رہے اور (آخر) اس وقت کو پہنچ گئے جو تو نے ہمارے لیے مقرر کیا تھا خدا فرمائے گا (اب) تمہارا ٹھکانہ دوزخ ہے ہمیشہ اس میں (جلتے) رہو گے مگر جو خدا چاہے بےشک تمہارا پروردگار دانا اور خبردار ہے','˹Consider˺ the Day He will gather them ˹all˺ together and say, “O assembly of jinn! You misled humans in great numbers.” And their human associates will say, “Our Lord! We benefited from each other’s company, but now we have reached the term which You appointed for us.” ˹Then˺ He will say, “The Fire is your home, yours to stay in forever, except whoever Allah wills to spare.” Surely your Lord is All-Wise, All-Knowing','और (ऐ रसूल वह दिन याद दिलाओ) जिस दिन ख़ुदा सब लोगों को जमा करेगा और शयातीन से फरमाएगा, ऐ गिरोह जिन्नात तुमने तो बहुतेरे आदमियों को (बहका बहका कर) अपनी जमाअत बड़ी कर ली (और) आदमियों से जो लोग (उन शयातीन के दुनिया में) दोस्त थे कहेंगे ऐ हमारे पालने वाले (दुनिया में) हमने एक दूसरे से फायदा हासिल किया और अपने किए की सज़ा पाने को, जो वक्त तू ने हमारे लिए मुअय्युन किया था अब हम अपने उस वक्त (क़यामत) में पहुँच गए ख़ुदा उसके जवाब में, फरमाएगा तुम सब का ठिकाना जहन्नुम है और उसमें हमेशा रहोगे मगर जिसे ख़ुदा चाहे (नजात दे) बेशक तेरा परवरदिगार हिकमत वाला वाक़िफकार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,129,'Al-An''aam','وَكَذَٰلِكَ نُوَلِّي بَعۡضَ ٱلظَّٰلِمِينَ بَعۡضَۢا بِمَا كَانُواْ يَكۡسِبُونَ','اور اسی طرح ہم ظالموں کو ان کے اعمال کے سبب جو وہ کرتے تھے ایک دوسرے پر مسلط کر دیتے ہیں','This is how We make the wrongdoers ˹destructive˺ allies of one another because of their misdeeds','और इसी तरह हम बाज़ ज़ालिमों को बाज़ का उनके करतूतों की बदौलत सरपरस्त बनाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,130,'Al-An''aam','يَٰمَعۡشَرَ ٱلۡجِنِّ وَٱلۡإِنسِ أَلَمۡ يَأۡتِكُمۡ رُسُلࣱ مِّنكُمۡ يَقُصُّونَ عَلَيۡكُمۡ ءَايَٰتِي وَيُنذِرُونَكُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَاۚ قَالُواْ شَهِدۡنَا عَلَىٰٓ أَنفُسِنَاۖ وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَشَهِدُواْ عَلَىٰٓ أَنفُسِهِمۡ أَنَّهُمۡ كَانُواْ كَٰفِرِينَ','اے جنّوں اور انسانوں کی جماعت کیا تمہارے پاس تم ہی میں سے پیغمبر نہیں آتے رہے جو میری آیتیں تم کو پڑھ پڑھ کر سناتے اور اس دن کے سامنے آموجود ہونے سے ڈراتے تھے وہ کہیں گے کہ (پروردگار) ہمیں اپنے گناہوں کا اقرار ہے ان لوگوں کو دنیاکی زندگی نے دھوکے میں ڈال رکھا تھا اور (اب) خود اپنے اوپر گواہی دی کہ کفر کرتے تھے','˹Allah will ask,˺ “O assembly of jinn and humans! Did messengers not come from among you, proclaiming My revelations and warning you of the coming of this Day of yours?” They will say, “We confess against ourselves!” For they have been deluded by ˹their˺ worldly life. And they will testify against themselves that they were disbelievers','(फिर हम पूछेंगे कि क्यों) ऐ गिरोह जिन व इन्स क्या तुम्हारे पास तुम ही में के पैग़म्बर नहीं आए जो तुम तुमसे हमारी आयतें बयान करें और तुम्हें तुम्हारे उस रोज़ (क़यामत) के पेश आने से डराएँ वह सब अर्ज करेंगे (बेशक आए थे) हम ख़ुद अपने ऊपर आप अपने (ख़िलाफ) गवाही देते हैं (वाकई) उनको दुनिया की (चन्द रोज़) ज़िन्दगी ने उन्हें अंधेरे में डाल रखा और उन लोगों ने अपने ख़िलाफ आप गवाही दीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,131,'Al-An''aam','ذَٰلِكَ أَن لَّمۡ يَكُن رَّبُّكَ مُهۡلِكَ ٱلۡقُرَىٰ بِظُلۡمࣲ وَأَهۡلُهَا غَٰفِلُونَ','(اے محمدﷺ!) یہ (جو پیغمبر آتے رہے اور کتابیں نازل ہوتی رہیں تو) اس لیے کہ تمہارا پروردگار ایسا نہیں کہ بستیوں کو ظلم سے ہلاک کر دے اور وہاں کے رہنے والوں کو (کچھ بھی) خبر نہ ہو','This ˹sending of the messengers˺ is because your Lord would never destroy a society for their wrongdoing while its people are unaware ˹of the truth˺','बेशक ये सब के सब काफिर थे और ये (पैग़म्बरों का भेजना सिर्फ) उस वजह से है कि तुम्हारा परवरदिगार कभी बस्तियों को ज़ुल्म ज़बरदस्ती से वहाँ के बाशिन्दों के ग़फलत की हालत में हलाक नहीं किया करता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,132,'Al-An''aam','وَلِكُلࣲّ دَرَجَٰتࣱ مِّمَّا عَمِلُواْۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا يَعۡمَلُونَ','اور سب لوگوں کے بلحاظ اعمال درجے (مقرر) ہیں اور جو کام یہ لوگ کرتے ہیں خدا ان سے بے خبر نہیں','They will each be assigned ranks according to their deeds. And your Lord is not unaware of what they do','और जिसने जैसा (भला या बुरा) किया है उसी के मुवाफ़िक हर एक के दरजात हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,133,'Al-An''aam','وَرَبُّكَ ٱلۡغَنِيُّ ذُو ٱلرَّحۡمَةِۚ إِن يَشَأۡ يُذۡهِبۡكُمۡ وَيَسۡتَخۡلِفۡ مِنۢ بَعۡدِكُم مَّا يَشَآءُ كَمَآ أَنشَأَكُم مِّن ذُرِّيَّةِ قَوۡمٍ ءَاخَرِينَ','اور تمہارا پروردگار بےپروا (اور) صاحب رحمت ہے اگر چاہے (تو اے بندوں) تمہیں نابود کر دے اور تمہارے بعد جن لوگوں کو چاہے تمہارا جانشین بنا دے جیسا تم کو بھی دوسرے لوگوں کی نسل سے پیدا کیا ہے','Your Lord is the Self-Sufficient, Full of Mercy. If He wills, He can do away with you and replace you with whoever He wills, just as He produced you from the offspring of other people','और जो कुछ वह लोग करते हैं तुम्हारा परवरदिगार उससे बेख़बर नहीं और तुम्हारा परवरदिगार बे परवाह रहम वाला है - अगर चाहे तो तुम सबके सबको (दुनिया से उड़ा) ले लाए और तुम्हारे बाद जिसको चाहे तुम्हार जानशीन बनाए जिस तरह आख़िर तुम्हें दूसरे लोगों की औलाद से पैदा किया है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,134,'Al-An''aam','إِنَّ مَا تُوعَدُونَ لَأٓتࣲۖ وَمَآ أَنتُم بِمُعۡجِزِينَ','کچھ شک نہیں کہ جو وعدہ تم سے کیا جاتا ہے وہ (وقوع میں) آنے والا ہے اور تم (خدا کو) مغلوب نہیں کر سکتے','Indeed, what you have been promised will certainly come to pass. And you will have no escape','बेशक जिस चीज़ का तुमसे वायदा किया जाता है वह ज़रूर (एक न एक दिन) आने वाली है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,135,'Al-An''aam','قُلۡ يَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَامِلࣱۖ فَسَوۡفَ تَعۡلَمُونَ مَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّٰلِمُونَ','کہہ دو کہ لوگو تم اپنی جگہ عمل کئے جاؤ میں (اپنی جگہ) عمل کئے جاتا ہوں عنقریب تم کو معلوم ہو جائے گا کہ آخرت میں (بہشت) کس کا گھر ہوگا کچھ شک نہیں کہ مشرک نجات نہیں پانے کے','Say, ˹O Prophet,˺ “O my people! Persist in your ways, for I ˹too˺ will persist in mine. You will soon know who will fare best in the end. Indeed, the wrongdoers will never succeed.”','और तुम उसके लाने में (ख़ुदा को) आजिज़ नहीं कर सकते (ऐ रसूल तुम उनसे) कहो कि ऐ मेरी क़ौम तुम बजाए ख़ुद जो चाहो करो मैं (बजाए ख़ुद) अमल कर रहा हूँ फिर अनक़रीब तुम्हें मालूम हो जाएगा कि आख़ेरत (बेहश्त) किसके लिए है (तुम्हारे लिए या हमारे लिए) ज़ालिम लोग तो हरगिज़ कामयाब न होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,136,'Al-An''aam','وَجَعَلُواْ لِلَّهِ مِمَّا ذَرَأَ مِنَ ٱلۡحَرۡثِ وَٱلۡأَنۡعَٰمِ نَصِيبࣰ ا فَقَالُواْ هَٰذَا لِلَّهِ بِزَعۡمِهِمۡ وَهَٰذَا لِشُرَكَآئِنَاۖ فَمَا كَانَ لِشُرَكَآئِهِمۡ فَلَا يَصِلُ إِلَى ٱللَّهِۖ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَآئِهِمۡۗ سَآءَ مَا يَحۡكُمُونَ','اور (یہ لوگ) خدا ہی کی پیدا کی ہوئی چیزوں یعنی کھیتی اور چوپایوں میں خدا کا بھی ایک حصہ مقرر کرتے ہیں اور اپنے خیال (باطل) سے کہتے ہیں کہ یہ (حصہ) تو خدا کا اور یہ ہمارے شریکوں (یعنی بتوں) کا تو جو حصہ ان کے شریکوں کا ہوتا ہے وہ تو خدا کی طرف نہیں جا سکتا اور جو حصہ خدا کا ہوتا ہے وہ ان کے شریکوں کی طرف جا سکتا ہے یہ کیسا برا انصاف ہے','The pagans set aside for Allah a share of the crops and cattle He created, saying, “This ˹portion˺ is for Allah,” so they claim, “and this ˹one˺ for our associate-gods.” Yet the portion of their associate-gods is not shared with Allah while Allah’s portion is shared with their associate-gods. What unfair judgment','और ये लोग ख़ुदा की पैदा की हुई खेती और चौपायों में से हिस्सा क़रार देते हैं और अपने ख्याल के मुवाफिक कहते हैं कि ये तो ख़ुदा का (हिस्सा) है और ये हमारे शरीकों का (यानि जिनको हमने ख़ुदा का शरीक बनाया) फिर जो ख़ास उनके शरीकों का है वह तो ख़ुदा तक नहीं पहुँचने का और जो हिस्सा ख़ुदा का है वो उसके शरीकों तक पहुँच जाएगा ये क्या ही बुरा हुक्म लगाते हैं और उसी तरह बहुतेरे मुशरकीन को उनके शरीकों ने अपने बच्चों को मार डालने को अच्छा कर दिखाया है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,137,'Al-An''aam','وَكَذَٰلِكَ زَيَّنَ لِكَثِيرࣲ مِّنَ ٱلۡمُشۡرِكِينَ قَتۡلَ أَوۡلَٰدِهِمۡ شُرَكَآؤُهُمۡ لِيُرۡدُوهُمۡ وَلِيَلۡبِسُواْ عَلَيۡهِمۡ دِينَهُمۡۖ وَلَوۡ شَآءَ ٱللَّهُ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا يَفۡتَرُونَ','اسی طرح بہت سے مشرکوں کو ان کے شریکوں نے ان کے بچوں کو جان سے مار ڈالنا اچھا کر دکھایا ہے تاکہ انہیں ہلاکت میں ڈال دیں اور ان کے دین کو ان پر خلط ملط کر دیں اور اگر خدا چاہتا تو وہ ایسا نہ کرتے تو ان کو چھوڑ دو کہ وہ جانیں اور ان کا جھوٹ','Likewise, the pagans’ evil associates have made it appealing to them to kill their own children—only leading to their destruction as well as confusion in their faith. Had it been Allah’s Will, they would not have done such a thing. So leave them and their falsehood','ताकि उन्हें (बदी) हलाकत में डाल दें और उनके सच्चे दीन को उन पर मिला जुला दें और अगर ख़ुदा चाहता तो लोग ऐसा काम न करते तो तुम (ऐ रसूल) और उनकी इफ़तेरा परदाज़ियों को (ख़ुदा पर) छोड़ दो और ये लोग अपने ख्याल के मुवाफिक कहने लगे कि ये चौपाए और ये खेती अछूती है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,138,'Al-An''aam','وَقَالُواْ هَٰذِهِۦٓ أَنۡعَٰمࣱ وَحَرۡثٌ حِجۡرࣱ لَّا يَطۡعَمُهَآ إِلَّا مَن نَّشَآءُ بِزَعۡمِهِمۡ وَأَنۡعَٰمٌ حُرِّمَتۡ ظُهُورُهَا وَأَنۡعَٰمࣱ لَّا يَذۡكُرُونَ ٱسۡمَ ٱللَّهِ عَلَيۡهَا ٱفۡتِرَآءً عَلَيۡهِۚ سَيَجۡزِيهِم بِمَا كَانُواْ يَفۡتَرُونَ','اور اپنے خیال سے یہ بھی کہتے ہیں کہ یہ چارپائے اور کھیتی منع ہے اسے اس شخص کے سوا جسے ہم چاہیں کوئی نہ کھائے اور (بعض) چارپائے ایسے ہیں کہ ان کی پیٹ پر چڑھنا منع کر دیا گیا ہے اور بعض مویشی ایسے ہیں جن پر (ذبح کرتے وقت) خدا کا نام نہیں لیتے سب خدا پر جھوٹ ہے وہ عنقریب ان کو ان کے جھوٹ کا بدلہ دے گا','They say, “These cattle and crops are reserved—none may eat them except those we permit,” so they claim. Some other cattle are exempted from labour and others are not slaughtered in Allah’s Name—falsely attributing lies to Him. He will repay them for their lies','उनको सिवा उसके जिसे हम चाहें कोई नहीं खा सकता और (उनका ये भी ख्याल है) कि कुछ चारपाए ऐसे हैं जिनकी पीठ पर सवारी लादना हराम किया गया और कुछ चारपाए ऐसे है जिन पर (ज़िबह के वक्त) ख़ुदा का नाम तक नहीं लेते और फिर यह ढकोसले (ख़ुदा की तरफ मनसूब करते) हैं ये सब ख़ुदा पर इफ़तेरा व बोहतान है ख़ुदा उनके इफ़तेरा परदाज़ियों को बहुत जल्द सज़ा देगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,139,'Al-An''aam','وَقَالُواْ مَا فِي بُطُونِ هَٰذِهِ ٱلۡأَنۡعَٰمِ خَالِصَةࣱ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزۡوَٰجِنَاۖ وَإِن يَكُن مَّيۡتَةࣰ فَهُمۡ فِيهِ شُرَكَآءُۚ سَيَجۡزِيهِمۡ وَصۡفَهُمۡۚ إِنَّهُۥ حَكِيمٌ عَلِيمࣱ‏','اور یہ بھی کہتے ہیں کہ جو بچہ ان چارپایوں کے پیٹ میں ہے وہ خاص ہمارے مردوں کے لئے ہے اور ہماری عورتوں کو (اس کا کھانا) حرام ہے اور اگر وہ بچہ مرا ہوا ہو تو سب اس میں شریک ہیں (یعنی اسے مرد اور عورتیں سب کھائیں) عنقریب خدا ان کو ان کے ڈھکوسلوں کی سزا دے گا بےشک وہ حکمت والا خبردار ہے','They ˹also˺ say, “The offspring of this cattle is reserved for our males and forbidden to our females; but if it is stillborn, they may all share it.” He will repay them for their falsehood. Surely He is All-Wise, All-Knowing','और कुफ्फ़ार ये भी कहते हैं कि जो बच्चा (वक्त ़ज़बाह) उन जानवरों के पेट में है (जिन्हें हमने बुतों के नाम कर छोड़ा और ज़िन्दा पैदा होता तो) सिर्फ हमारे मर्दों के लिए हलाल है और हमारी औरतों पर हराम है और अगर वह मरा हुआ हो तो सब के सब उसमें शरीक हैं ख़ुदा अनक़रीब उनको बातें बनाने की सज़ा देगा बेशक वह हिकमत वाला बड़ा वाक़िफकार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,140,'Al-An''aam','قَدۡ خَسِرَ ٱلَّذِينَ قَتَلُوٓاْ أَوۡلَٰدَهُمۡ سَفَهَۢا بِغَيۡرِ عِلۡمࣲ وَحَرَّمُواْ مَا رَزَقَهُمُ ٱللَّهُ ٱفۡتِرَآءً عَلَى ٱللَّهِۚ قَدۡ ضَلُّواْ وَمَا كَانُواْ مُهۡتَدِينَ','جن لوگوں نے اپنی اولاد کو بیوقوفی سے بے سمجھی سے قتل کیا اور خدا پر افترا کر کے اس کی عطا فرمائی کی ہوئی روزی کو حرام ٹہرایا وہ گھاٹے میں پڑ گئے وہ بےشبہ گمراہ ہیں اور ہدایت یافتہ نہیں ہیں','Lost indeed are those who have murdered their own children foolishly out of ignorance and have forbidden what Allah has provided for them—falsely attributing lies to Allah. They have certainly strayed and are not ˹rightly˺ guided','बेशक जिन लोगों ने अपनी औलाद को बे समझे बूझे बेवकूफी से मार डाला और जो रोज़ी ख़ुदा ने उन्हें दी थी उसे ख़ुदा पर इफ़तेरा (बोहतान) बाँध कर अपने ऊपर हराम कर डाला और वह सख्त घाटे में है ये यक़ीनन राहे हक़ से भटक गऐ और ये हिदायत पाने वाले थे भी नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,141,'Al-An''aam','۞وَهُوَ ٱلَّذِيٓ أَنشَأَ جَنَّٰتࣲ مَّعۡرُوشَٰتࣲ وَغَيۡرَ مَعۡرُوشَٰتࣲ وَٱلنَّخۡلَ وَٱلزَّرۡعَ مُخۡتَلِفًا أُكُلُهُۥ وَٱلزَّيۡتُونَ وَٱلرُّمَّانَ مُتَشَٰبِهࣰ ا وَغَيۡرَ مُتَشَٰبِهࣲۚ كُلُواْ مِن ثَمَرِهِۦٓ إِذَآ أَثۡمَرَ وَءَاتُواْ حَقَّهُۥ يَوۡمَ حَصَادِهِۦۖ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ','اور خدا ہی تو ہے جس نے باغ پیدا کئے چھتریوں پر چڑھائے ہوئے بھی اور جو چھتریوں پر نہیں چڑھائے ہوئے وہ بھی اور کھجور اور کھیتی جن کے طرح طرح کے پھل ہوتے ہیں اور زیتون اور انار جو (بعض باتوں میں) ایک دوسرے سے ملتے ہیں جب یہ چیزیں پھلیں تو ان کے پھل کھاؤ اور جس دن (پھل توڑو اور کھیتی) کاٹو تو خدا کا حق بھی اس میں سے ادا کرو اور بےجا نہ اڑاؤ کہ خدا بیجا اڑانے والوں کو دوست نہیں رکھتا','He is the One Who produces gardens—both cultivated and wild—and palm trees, crops of different flavours, olives, and pomegranates—similar ˹in shape˺, but dissimilar ˹in taste˺. Eat of the fruit they bear and pay the dues at harvest, but do not waste. Surely He does not like the wasteful','और वह तो वही ख़ुदा है जिसने बहुतेरे बाग़ पैदा किए (जिनमें मुख्तलिफ दरख्त हैं - कुछ तो अंगूर की तरह टट्टियों पर) चढ़ाए हुए और (कुछ) बे चढ़ाए हुए और खजूर के दरख्त और खेती जिसमें फल मुख्तलिफ़ किस्म के हैं और ज़ैतून और अनार बाज़ तो सूरत रंग मज़े में, मिलते जुलते और (बाज़) बेमेल (लोगों) जब ये चीज़े फलें तो उनका फल खाओ और उन चीज़ों के काटने के दिन ख़ुदा का हक़ (ज़कात) दे दो और ख़बरदार फज़ूल ख़र्ची न करो - क्यों कि वह (ख़ुदा) फुज़ूल ख़र्चे से हरगिज़ उलफत नहीं रखता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,142,'Al-An''aam','وَمِنَ ٱلۡأَنۡعَٰمِ حَمُولَةࣰ وَفَرۡشࣰ اۚ كُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوࣱّ مُّبِينࣱ‏','اور چارپایوں میں بوجھ اٹھانے والے (یعنی بڑے بڑے) بھی پیدا کئے اور زمین سے لگے ہوئے (یعنی چھوٹے چھوٹے) بھی (پس) خدا کا دیا ہوا رزق کھاؤ اور شیطان کے قدموں پر نہ چلو وہ تمہارا صریح دشمن ہے','Some cattle are fit for labour, others are too small. Eat of what Allah has provided for you and do not follow Satan’s footsteps. Certainly, he is your sworn enemy','और चारपायों में से कुछ तो बोझ उठाने वाले (बड़े बड़े) और कुछ ज़मीन से लगे हुए (छोटे छोटे) पैदा किए ख़ुदा ने जो तुम्हें रोज़ी दी है उस में से खाओ और शैतान के क़दम ब क़दम न चलो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,143,'Al-An''aam','ثَمَٰنِيَةَ أَزۡوَٰجࣲۖ مِّنَ ٱلضَّأۡنِ ٱثۡنَيۡنِ وَمِنَ ٱلۡمَعۡزِ ٱثۡنَيۡنِۗ قُلۡ ءَآلذَّكَرَيۡنِ حَرَّمَ أَمِ ٱلۡأُنثَيَيۡنِ أَمَّا ٱشۡتَمَلَتۡ عَلَيۡهِ أَرۡحَامُ ٱلۡأُنثَيَيۡنِۖ نَبِّـُٔونِي بِعِلۡمٍ إِن كُنتُمۡ صَٰدِقِينَ','(یہ بڑے چھوٹے چارپائے) آٹھ قسم کے (ہیں) دو (دو) بھیڑوں میں سے اور دو (دو) بکریوں میں سے (یعنی ایک ایک نر اور اور ایک ایک مادہ) (اے پیغمبر ان سے) پوچھو کہ (خدا نے) دونوں (کے) نروں کو حرام کیا ہے یا دونوں (کی) مادنیوں کو یا جو بچہ مادنیوں کے پیٹ میں لپٹ رہا ہو اسے اگر سچے ہو تو مجھے سند سے بتاؤ','˹Allah has created˺ four pairs: a pair of sheep and a pair of goats—ask ˹them, O Prophet˺, “Has He forbidden ˹to you˺ the two males or the two females or what is in the wombs of the two females? Tell me with knowledge, if what you say is true.”—','(क्यों कि) वह तो यक़ीनन तुम्हारा खुला हुआ दुश्मन है (ख़ुदा ने नर मादा मिलाकर) आठ (क़िस्म के) जोड़े पैदा किए हैं - भेड़ से (नर मादा) दो और बकरी से (नर मादा) दो (ऐ रसूल उन काफिरों से) पूछो तो कि ख़ुदा ने (उन दोनों भेड़ बकरी के) दोनों नरों को हराम कर दिया है या उन दोनों मादनियों को या उस बच्चे को जो उन दोनों मादनियों के पेट से अन्दर लिए हुए हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,144,'Al-An''aam','وَمِنَ ٱلۡإِبِلِ ٱثۡنَيۡنِ وَمِنَ ٱلۡبَقَرِ ٱثۡنَيۡنِۗ قُلۡ ءَآلذَّكَرَيۡنِ حَرَّمَ أَمِ ٱلۡأُنثَيَيۡنِ أَمَّا ٱشۡتَمَلَتۡ عَلَيۡهِ أَرۡحَامُ ٱلۡأُنثَيَيۡنِۖ أَمۡ كُنتُمۡ شُهَدَآءَ إِذۡ وَصَّىٰكُمُ ٱللَّهُ بِهَٰذَاۚ فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبࣰ ا لِّيُضِلَّ ٱلنَّاسَ بِغَيۡرِ عِلۡمٍۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ','اور دو (دو) اونٹوں میں سے اور دو (دو) گایوں میں سے (ان کے بارے میں بھی ان سے) پوچھو کہ (خدا نے) دونوں (کے) نروں کو حرام کیا ہے یا دونوں (کی) مادنیوں کو یا جو بچہ مادنیوں کے پیٹ میں لپٹ رہا ہو اس کو بھلا جس وقت خدا نے تم کو اس کا حکم دیا تھا تم اس وقت موجود تھے؟ تو اس شخص سے زیادہ کون ظالم ہے جو خدا پر جھوٹ افتراء کرے تاکہ اِز راہ بے دانشی لوگوں کو گمراہ کرے کچھ شک نہیں کہ خدا ظالم لوگوں کو ہدایت نہیں دیتا','and a pair of camels and a pair of oxen. Ask ˹them˺, “Has He forbidden ˹to you˺ the two males or the two females or what is in the wombs of the two females? Or were you present when Allah gave you this commandment?” Who does more wrong than those who fabricate lies against Allah to mislead others without ˹any˺ knowledge? Surely Allah does not guide the wrongdoing people','अगर तुम सच्चे हो तो ज़रा समझ के मुझे बताओ और ऊँट के (नर मादा) दो और गाय के (नर मादा) दो (ऐ रसूल तुम उनसे) पूछो कि ख़ुदा ने उन दोनों (ऊँट गाय के) नरों को हराम किया या दोनों मादनियोंको या उस बच्चे को जो दोनों मादनियों के पेट अपने अन्दर लिये हुए है क्या जिस वक्त ख़ुदा ने तुमको उसका हुक्म दिया था तुम उस वक्त मौजूद थे फिर जो ख़ुदा पर झूठ बोताहन बॉधे उससे ज्यादा ज़ालिम कौन होगा ताकि लोगों के वे समझे बूझे गुमराह करें ख़ुदा हरगिज़ ज़ालिम क़ौम में मंज़िले मक़सूद तक नहीं पहुचाता');
